/* Card set: Cheese (built from the approved roster.csv by the Cheese build).
   360 cards: Varieties, Dishes, Making, Lore, Serving.
   Art: real photography via Wikimedia Commons (Special:FilePath, width=1024). */
CardSets.register({"id":"cheese","name":"Cheese","code":"CHEZ","description":"360 cards celebrating cheese in all its glory — 160 varieties, 60 cheese-led dishes, 40 ways it is made, 50 festivals, tales and lore, and 50 wheels, rinds, tools and ways to serve it.","theme":{"primary":"#8a5f14","secondary":"#f2b63d","artBackground":"#2a1d08","artFit":"cover"},"pack":{"name":"Cheese Pack","emblem":"🧀","skin":"cheese","slots":[{"count":5,"label":"Common","odds":{"common":100}},{"count":2,"label":"Uncommon","odds":{"uncommon":100}},{"count":1,"label":"Wild card","odds":{"common":55,"uncommon":30,"rare":12,"epic":3}},{"count":1,"label":"Rare or better (guaranteed)","odds":{"rare":81.8,"epic":14,"legendary":4,"chase":0.2}}]},"cards":[{"name":"Casu Martzu","rarity":"chase","id":"casu-martzu","subtitle":"Variety","details":"Sardinian sheep cheese ripened with live maggots that soften the paste; banned in many places and prized as a daring delicacy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Casu%20Marzu%20cheese.jpg?width=1024"},{"name":"Cave Aging","rarity":"chase","id":"cave-aging","subtitle":"Making","details":"Cool, humid caves hold steady temperatures year-round, letting wheels age slowly while native moulds shape their rinds and flavour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meule%20du%20Plateau%20cheese%20wheels%20in%20the%20ripening%20cellar%2C%20Terre%20de%20fromages%2C%20Herve%2C%202025.jpg?width=1024"},{"name":"Cooper's Hill Cheese-Rolling","rarity":"chase","id":"coopers-hill-cheese-rolling","subtitle":"Lore","details":"Racers chase a wheel of Double Gloucester down a near-vertical hill, tumbling after cheese that can hit highway speeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20race%20at%20the%20Cooper%27s%20Hill%20Cheese%20Rolling%20and%20Wake%2C%20on%20Cooper%27s%20Hill%2C%20Brockworth%2C%20Gloucestershire%2C%20on%2027%20May%202013.jpg?width=1024"},{"name":"Fondue","rarity":"chase","id":"fondue","subtitle":"Dish","details":"Swiss melted cheese served communally in a pot over a flame where diners dip bread using long forks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Swiss%20cheese%20fondue.JPG?width=1024"},{"name":"Moon Cheese","rarity":"chase","id":"moon-cheese","subtitle":"Lore","details":"For centuries the Moon was joked to be green cheese, a young unripened cheese, because its craters looked like a wheel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moon%20cheese%20%2851522433752%29.jpg?width=1024"},{"name":"Parmigiano Reggiano","rarity":"chase","id":"parmigiano-reggiano","subtitle":"Variety","details":"Italy's king of cheeses: raw cow's milk, cooked and pressed, then aged for years until hard, granular and deeply savoury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Parmigiano%20Reggiano%20meules%20MIN%20Rungis.jpg?width=1024"},{"name":"Pule","rarity":"chase","id":"pule","subtitle":"Variety","details":"Serbian cheese made from donkey milk in tiny amounts; its scarcity and labour make it among the world's priciest cheeses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Specijalni%20rezervat%20prirode%20Zasavica%20002.jpg?width=1024"},{"name":"Raclette","rarity":"chase","id":"raclette","subtitle":"Dish","details":"A Swiss wheel is heated and the molten layer scraped over potatoes and pickles right at the table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pataclette.jpg?width=1024"},{"name":"Roquefort","rarity":"chase","id":"roquefort","subtitle":"Variety","details":"France's famous sheep's-milk blue, ripened in the Combalou caves where natural mould gives it a sharp, tangy bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wikicheese%20-%20Roquefort%20-%2020150417%20-%20002.jpg?width=1024"},{"name":"The Cheese Wedding Cake","rarity":"chase","id":"the-cheese-wedding-cake","subtitle":"Serving","details":"Stacked whole wheels tiered like a wedding cake, cut at the table and served with fruit, honey and crackers instead of sponge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20wedding%20cake%20decorated%20with%20figs%20and%20grapes.jpg?width=1024"},{"name":"3,800-Year-Old Mummy Cheese","rarity":"legendary","id":"3800-year-old-mummy-cheese","subtitle":"Lore","details":"Lumps of cheese buried with mummies in China's Xiaohe cemetery survived about 3,800 years in the dry desert air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Xiaohe%20mummy%20in%20XUAR%20Museum%2001.jpg?width=1024"},{"name":"Adjaruli Khachapuri","rarity":"legendary","id":"adjaruli-khachapuri","subtitle":"Dish","details":"Georgian cheese-filled bread shaped like a boat and finished with a knob of butter and an egg yolk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Khachapuri%20Adjaruli%20with%20egg%20and%20butter%202016.jpg?width=1024"},{"name":"Affineur","rarity":"legendary","id":"affineur","subtitle":"Making","details":"An affineur is a cheese-aging specialist who turns, brushes, and washes wheels for months, deciding when each is ready to eat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marche-aux-puces-Lausanne-004.jpg?width=1024"},{"name":"Aligot","rarity":"legendary","id":"aligot","subtitle":"Dish","details":"French mashed potatoes beaten with Tomme cheese and garlic until they stretch in long silky ribbons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bol%20d%27aligot.jpg?width=1024"},{"name":"Alkmaar Cheese Market","rarity":"legendary","id":"alkmaar-cheese-market","subtitle":"Lore","details":"Cheese porters in guild colours have weighed and carried great wheels at Alkmaar's market in the Netherlands for centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20cheese%20market%20at%20Alkmaar%20%282%29%2C%20illustration%20from%20The%20Encyclopedia%20of%20Food%20by%20Artemas%20Ward.jpg?width=1024"},{"name":"Brie","rarity":"legendary","id":"brie","subtitle":"Variety","details":"France's soft cow's-milk classic with a bloomy white rind, buttery centre and gentle mushroom aroma.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue%20brie%20cheese%20and%20Manchego.jpg?width=1024"},{"name":"Camembert","rarity":"legendary","id":"camembert","subtitle":"Variety","details":"Normandy cow's-milk cheese with a downy rind and rich, earthy paste that ripens from firm to gloriously runny.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%2820251230%29%20Camembert%20cheese%2003.jpg?width=1024"},{"name":"Cheese in Space","rarity":"legendary","id":"cheese-in-space","subtitle":"Lore","details":"In 2010 a wheel of Le Brouere secretly rode SpaceX's Dragon capsule into orbit, a nod to Monty Python's cheese shop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Space%20Cheese.jpg?width=1024"},{"name":"Comté","rarity":"legendary","id":"comte","subtitle":"Variety","details":"French Jura cow's-milk giant, pressed and aged in forts and caves; smooth, nutty and fruity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Comte%20AOP.jpg?width=1024"},{"name":"Cracking a Parmesan Wheel","rarity":"legendary","id":"cracking-a-parmesan-wheel","subtitle":"Serving","details":"A whole wheel is scored, wedged and opened with short knives so the interior breaks into fragrant, crystalline chunks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pannello%20coltelli%20da%20parmigiano%20%28serie%20di%2019%29%20-%20Musei%20del%20cibo%20-%20Parmigiano%20-%20187-206.tif?width=1024"},{"name":"Emmental","rarity":"legendary","id":"emmental","subtitle":"Variety","details":"Swiss cow's-milk cheese famed for its cherry-sized holes, formed by bubbles of gas during ripening; mild and nutty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Emmental%20Cheese%202holes.jpg?width=1024"},{"name":"Gorgonzola","rarity":"legendary","id":"gorgonzola","subtitle":"Variety","details":"Italian cow's-milk blue from Lombardy and Piedmont, ranging from sweet and spoonable to firm and piccante.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gorgonzola%201.jpg?width=1024"},{"name":"Gouda","rarity":"legendary","id":"gouda","subtitle":"Variety","details":"Dutch cow's-milk cheese named for its market town; young wheels are mild and creamy, aged wheels turn caramel-sweet and crunchy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Winterswijk%20%28NL%29%2C%20Wochenmarkt%20--%202024%20--%204337.jpg?width=1024"},{"name":"Gruyère","rarity":"legendary","id":"gruyere","subtitle":"Variety","details":"Swiss Alpine cow's-milk cheese, firm and nutty with a sweet finish; a cornerstone of fondue and gratins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20150125%20Le%20Gruy%C3%A8re%20AOP%20R%C3%A9serve%20-%20Der%20Schweizer%20-%20WikiLovesCheese%20Vienna%208830.jpg?width=1024"},{"name":"Manchego","rarity":"legendary","id":"manchego","subtitle":"Variety","details":"Spanish sheep's-milk cheese from La Mancha, firm and buttery with a zigzag rind and a piquant, nutty tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr%20-%20cyclonebill%20-%20Manchego.jpg?width=1024"},{"name":"Mozzarella di Bufala","rarity":"legendary","id":"mozzarella-di-bufala","subtitle":"Variety","details":"Campania buffalo-milk mozzarella: porcelain-white, elastic and juicy, with a fresh lactic tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mozzarella%20di%20bufala3.jpg?width=1024"},{"name":"Pecorino Romano","rarity":"legendary","id":"pecorino-romano","subtitle":"Variety","details":"Italy's hard sheep's-milk grating cheese, salty and sharp; made in Sardinia, Lazio and Grosseto.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pecorino%20romano%20cheese.jpg?width=1024"},{"name":"Penicillium Roqueforti","rarity":"legendary","id":"penicillium-roqueforti","subtitle":"Making","details":"This blue mould, added to curd or grown in pierced wheels, creates the veins and sharp, salty bite of blue cheeses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blauschimmelk%C3%A4se%20IMGP5469%20wp.jpg?width=1024"},{"name":"Poutine","rarity":"legendary","id":"poutine","subtitle":"Dish","details":"A Quebec dish of fries topped with fresh cheese curds and hot brown gravy that softens the curds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Poutine%20d%C3%A9jeuner.jpg?width=1024"},{"name":"Queen Victoria's Giant Cheddar","rarity":"legendary","id":"queen-victorias-giant-cheddar","subtitle":"Lore","details":"Somerset cheesemakers gave Queen Victoria a wedding gift with real weight: a single Cheddar wheel of about 1,100 pounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queen%20Victoria%20by%20Bassano.jpg?width=1024"},{"name":"Rennet","rarity":"legendary","id":"rennet","subtitle":"Making","details":"Rennet is an enzyme mix, traditionally from calves' stomachs, that sets liquid milk into a firm curd in under an hour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manufacture%20of%20cheese%20of%20the%20cheddar%20type%20from%20pasteurized%20milk%20%281913%29%20%2814779482522%29.jpg?width=1024"},{"name":"Saganaki","rarity":"legendary","id":"saganaki","subtitle":"Dish","details":"Greek cheese floured and pan-fried until crisp outside and molten inside then served sizzling.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saganaki.jpg?width=1024"},{"name":"Stilton","rarity":"legendary","id":"stilton","subtitle":"Variety","details":"England's celebrated blue: cow's milk, crumbly yet creamy, veined with mould for a rich, spicy depth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue%20Stilton%2008.jpg?width=1024"},{"name":"Stilton Village","rarity":"legendary","id":"stilton-village","subtitle":"Lore","details":"Stilton cheese took its name from this Cambridgeshire village where coaches stopped, though the cheese itself is made elsewhere.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stilton%20Village%20sign%20on%20North%20Street%20-%20geograph.org.uk%20-%205010589.jpg?width=1024"},{"name":"Tartiflette","rarity":"legendary","id":"tartiflette","subtitle":"Dish","details":"A Savoyard bake of potatoes and onions crowned with Reblochon cheese melted down into the dish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Une%20tartiflette%20sortie%20du%20four.jpg?width=1024"},{"name":"The Cheese Trolley","rarity":"legendary","id":"the-cheese-trolley","subtitle":"Serving","details":"A rolling cart of ripe cheeses wheeled to the table, where each piece is cut to order and explained by the server.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Cart%20in%20Gordon%20Ramsay%20restaurant.JPG?width=1024"},{"name":"The Girolle","rarity":"legendary","id":"the-girolle","subtitle":"Serving","details":"A Swiss tool that shaves Tête de Moine into delicate rosettes by turning a blade around a central pin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Girolle%207910.jpg?width=1024"},{"name":"Époisses","rarity":"legendary","id":"epoisses","subtitle":"Variety","details":"French cow's-milk cheese washed in marc brandy; famously pungent outside, silky and savoury within.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Epoisses%20Germain.jpg?width=1024"},{"name":"Asiago","rarity":"epic","id":"asiago","subtitle":"Variety","details":"Italian cow's-milk cheese from the Asiago plateau; fresh is soft and mild, aged is hard and nutty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asiago%20cheese%201.jpg?width=1024"},{"name":"Bloomy Rind","rarity":"epic","id":"bloomy-rind","subtitle":"Serving","details":"The white, downy coat on Brie-style cheeses is living mould that softens the paste from the outside in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brain%20cheese%20%286142694234%29.jpg?width=1024"},{"name":"Brining","rarity":"epic","id":"brining","subtitle":"Making","details":"Many wheels soak in salty brine for hours or days; the salt seasons them, firms the rind, and slows unwanted bacteria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White%20brine%20cheese%202.jpg?width=1024"},{"name":"Burrata","rarity":"epic","id":"burrata","subtitle":"Variety","details":"Puglian cow's-milk pouch of mozzarella filled with stracciatella and cream; delicate, milky and luscious.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burrata%20cheese.jpg?width=1024"},{"name":"Caprese","rarity":"epic","id":"caprese","subtitle":"Dish","details":"An Italian pairing of mozzarella and tomato with basil and olive oil where the cheese stays fresh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mozzarella%20and%20tomato%20salad%20in%20brown.jpg?width=1024"},{"name":"Cheddaring","rarity":"epic","id":"cheddaring","subtitle":"Making","details":"In cheddaring, slabs of warm curd are stacked and turned repeatedly, squeezing out whey and building a dense, layered texture.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheddar%20cheese%20making%20%281895%29%20%2820603824095%29.jpg?width=1024"},{"name":"Cheese Dreams","rarity":"epic","id":"cheese-dreams","subtitle":"Lore","details":"Folklore blames cheese for wild dreams, but a cheese-board study found sleepers reported surprisingly pleasant ones.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Child%20dreaming%20of%20Santa%20Claus%20cph.3b11721.jpg?width=1024"},{"name":"Cheese Wire Cutter","rarity":"epic","id":"cheese-wire-cutter","subtitle":"Serving","details":"A taut wire slices soft and semi-soft cheeses cleanly, without dragging or crushing the paste beneath the rind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20wire.png?width=1024"},{"name":"Clothbound Wheel","rarity":"epic","id":"clothbound-wheel","subtitle":"Serving","details":"Wrapped in cloth and rubbed with fat as it ages, a clothbound wheel breathes and develops a firm, earthy rind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WikiCheese%20-%20Montgomery%27s%20Cheddar%20Somerset%2001.jpg?width=1024"},{"name":"Edam","rarity":"epic","id":"edam","subtitle":"Variety","details":"Dutch cow's-milk cheese in its red wax coat; mild, firm and sliceable, made to travel well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SmallEdamCheese.jpg?width=1024"},{"name":"Farmhouse Cheddar","rarity":"epic","id":"farmhouse-cheddar","subtitle":"Variety","details":"English farmhouse cow's-milk Cheddar, clothbound and cave- or cellar-aged for a firm bite and earthy tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Somerset-Cheddar.jpg?width=1024"},{"name":"Feta","rarity":"epic","id":"feta","subtitle":"Variety","details":"Greek brined curd cheese, usually sheep's milk with some goat; crumbly, tangy and salty from its brine bath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Feta%20Greece%202.jpg?width=1024"},{"name":"Fontina","rarity":"epic","id":"fontina","subtitle":"Variety","details":"Val d'Aosta cow's-milk cheese, semi-soft and earthy with a superb melt; protected since the 12th century era of Alpine dairies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fontina%20PDO.jpg?width=1024"},{"name":"Fried Cheese Curds","rarity":"epic","id":"fried-cheese-curds","subtitle":"Dish","details":"Batter-coated cheese curds deep-fried until crisp with the cheese stretching at the first bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CheeseCurds.jpg?width=1024"},{"name":"Halloumi","rarity":"epic","id":"halloumi","subtitle":"Variety","details":"Cypriot brined cheese, traditionally sheep and goat milk, that holds its shape for grilling and frying; salty and squeaky.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grilled%20Halloumi.jpg?width=1024"},{"name":"Halloumi Fries","rarity":"epic","id":"halloumi-fries","subtitle":"Dish","details":"Sticks of halloumi coated and fried until golden while the salty cheese stays firm inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burger%20King%27s%20Halloumi%20Fries%202025-05-21.jpg?width=1024"},{"name":"Havarti","rarity":"epic","id":"havarti","subtitle":"Variety","details":"Danish cow's-milk semi-soft cheese, buttery and mild with tiny holes; often flavoured with dill or caraway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cream%20havarti%20on%20bread.jpg?width=1024"},{"name":"Jarlsberg","rarity":"epic","id":"jarlsberg","subtitle":"Variety","details":"Norwegian cow's-milk wheel with large round holes, sweet and nutty, modelled on Swiss Emmental styles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jarlsberg%20cheese.jpg?width=1024"},{"name":"Käsespätzle","rarity":"epic","id":"kasespatzle","subtitle":"Dish","details":"Soft German egg noodles layered with Emmental cheese and topped with crispy fried onions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2015%200718%20K%C3%A4sesp%C3%A4tzle%20S%C3%B6lden.jpg?width=1024"},{"name":"Limburger","rarity":"epic","id":"limburger","subtitle":"Variety","details":"German-Belgian washed-rind cow's-milk cheese, famously strong-smelling yet mild, creamy and meaty inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20limburger%20edit.jpg?width=1024"},{"name":"Morbier","rarity":"epic","id":"morbier","subtitle":"Variety","details":"French cow's-milk cheese split by a thin line of ash, once made from two milkings; fruity and creamy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morbier%20%28fromage%29%2001.jpg?width=1024"},{"name":"Mozzarella","rarity":"epic","id":"mozzarella","subtitle":"Variety","details":"Italian stretched-curd cheese, now usually cow's milk; mild, elastic and made to melt in long strands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mozzarella%20cheese.jpg?width=1024"},{"name":"Munster","rarity":"epic","id":"munster","subtitle":"Variety","details":"Alsace cow's-milk washed-rind cheese, barnyard-pungent outside and soft, savoury and spicy within.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Munster%2001.jpg?width=1024"},{"name":"Obatzda","rarity":"epic","id":"obatzda","subtitle":"Dish","details":"A Bavarian spread of ripe Camembert mashed with butter and paprika and served with pretzels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Obatzter-1.jpg?width=1024"},{"name":"Provoleta","rarity":"epic","id":"provoleta","subtitle":"Dish","details":"A thick slice of Argentine provolone grilled until blistered and seasoned with oregano and chilli.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Provoleta%20argentina%20%28cheese%29.jpg?width=1024"},{"name":"Provolone","rarity":"epic","id":"provolone","subtitle":"Variety","details":"Italian stretched-curd cow's-milk cheese, aged hanging in ropes; dolce is mild, piccante is sharp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Provolone%20layered.jpg?width=1024"},{"name":"Raw Milk","rarity":"epic","id":"raw-milk","subtitle":"Making","details":"Raw-milk cheese is made from unpasteurised milk, keeping native microbes that cheesemakers credit with deeper, more varied flavour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bouteilles%20commerce%20lait%20cru%20vache%20Aveyron%20sud.JPG?width=1024"},{"name":"Reblochon","rarity":"epic","id":"reblochon","subtitle":"Variety","details":"Savoy cow's-milk cheese with a washed rind and supple, nutty paste; the heart of tartiflette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reblochon%20AOC.jpg?width=1024"},{"name":"Red Leicester","rarity":"epic","id":"red-leicester","subtitle":"Variety","details":"English cow's-milk cheese coloured orange with annatto; firm, mellow and slightly nutty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red%20Leicester.jpg?width=1024"},{"name":"Say Cheese","rarity":"epic","id":"say-cheese","subtitle":"Lore","details":"Photographers ask for 'cheese' because saying it pulls the mouth into a smile shape just as the shutter clicks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Say%20Cheese%20%289696596420%29.jpg?width=1024"},{"name":"Starter Cultures","rarity":"epic","id":"starter-cultures","subtitle":"Making","details":"Carefully chosen bacteria are added to warm milk first; they eat lactose, make lactic acid, and start every cheese's flavour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%3B%20a%20short%20treatise%20on%20the%20manufacture%20of%20various%20kinds%20of%20domestic%20and%20foreign%20cheese%2C%20Cheddar%2C%20Dutch%2C%20Swiss%2C%20Italian%2C%20French%2C%20Limburger%2C%20Neufchatel%2C%20cream%2C%20cottage%20cheese%2C%20etc%20%281918%29%20%2820415852228%29.jpg?width=1024"},{"name":"Taleggio","rarity":"epic","id":"taleggio","subtitle":"Variety","details":"Lombard cow's-milk washed-rind cheese: pungent pink rind, soft bulging centre, fruity and tangy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taleggio%20Cheese.jpg?width=1024"},{"name":"The Big Cheese","rarity":"epic","id":"the-big-cheese","subtitle":"Lore","details":"Calling the boss 'the big cheese' began as slang for the real thing: 'the cheese' once meant the best of anything.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1904%20World%27s%20Fair%20Big%20Cheese%20Missouri%20Exhibit%20-%20DPLA%20-%20b983751eafb35aa49eba720414120d53.jpg?width=1024"},{"name":"The Cheese Course","rarity":"epic","id":"the-cheese-course","subtitle":"Serving","details":"Served after the main dish and before dessert in French tradition, it is a course built entirely around cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Business%20class%20cheese%20plate%20on%20Fiji%20Airways%20910.jpg?width=1024"},{"name":"The Cheese Shop Sketch","rarity":"epic","id":"the-cheese-shop-sketch","subtitle":"Lore","details":"Monty Python's 1972 cheese shop sketch lists dozens of cheeses and stocks none of them, not even a little Wensleydale.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NCI%20swiss%20cheese.jpg?width=1024"},{"name":"Wallace & Gromit's Moon Trip","rarity":"epic","id":"wallace-and-gromits-moon-trip","subtitle":"Lore","details":"In A Grand Day Out, Wallace builds a rocket to the Moon because the house has run out of cheese for crackers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Norland%20Scarecrow%20Festival%202019%20-%20Space%20and%20SciFi-%20A%20Grand%20Day%20Out.jpg?width=1024"},{"name":"Washed Rind","rarity":"epic","id":"washed-rind","subtitle":"Making","details":"Washed-rind cheeses are bathed in brine, beer, or spirits as they age, encouraging sticky orange rinds and famously pungent aromas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20150125%20WikiLovesCheese%20Vienna%208828.jpg?width=1024"},{"name":"Welsh Rarebit","rarity":"epic","id":"welsh-rarebit","subtitle":"Dish","details":"Toast topped with a rich sauce of cheddar and mustard that is grilled until bubbling and golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/T%40%20Welsh%20Rarebit%20-%20T%20%40%20The%20Dials%202023-05-28.jpg?width=1024"},{"name":"Wensleydale","rarity":"epic","id":"wensleydale","subtitle":"Variety","details":"Yorkshire cow's-milk cheese, crumbly and honeyed; famously paired with fruit cake in its home county.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wensleydale%20cheese%202.jpg?width=1024"},{"name":"World Cheese Awards","rarity":"epic","id":"world-cheese-awards","subtitle":"Lore","details":"Thousands of cheeses from dozens of countries are judged blind by experts to crown a World Champion Cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Handmade%20in%20Groningen%20-%20Winnaar%20van%202%20Great%20Taste%20awards%20in%20Engeland%21%20Banner%2C%20Oude%20Pekela%20%282019%29%2001.jpg?width=1024"},{"name":"Abondance","rarity":"rare","id":"abondance","subtitle":"Variety","details":"Savoy cow's-milk cheese with a concave rind edge, fruity and nutty with a gentle bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abondance%20%28fromage%29%2001.jpg?width=1024"},{"name":"Appenzeller","rarity":"rare","id":"appenzeller","subtitle":"Variety","details":"Swiss cow's-milk cheese washed in herbal brine, fruity and spicy; its recipe is a guarded secret.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bowl-shaped%20Appenzeller%20cheese.jpg?width=1024"},{"name":"Arepa de Queso","rarity":"rare","id":"arepa-de-queso","subtitle":"Dish","details":"Colombian and Venezuelan corn cakes filled or mixed with cheese and griddled until crisp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colombian%20Food%2C%20Arepas.jpg?width=1024"},{"name":"Beaufort","rarity":"rare","id":"beaufort","subtitle":"Variety","details":"French Alpine cow's-milk giant from Savoy, firm and floral, made in copper vats from summer milk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beaufort%20%28fromage%29%2001.jpg?width=1024"},{"name":"Beer Cheese Dip","rarity":"rare","id":"beer-cheese-dip","subtitle":"Dish","details":"A Kentucky spread blending sharp cheddar with beer and spices into a tangy pub-style dip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beer%20cheese%20dip.jpg?width=1024"},{"name":"Ben Gunn's Cheese","rarity":"rare","id":"ben-gunns-cheese","subtitle":"Lore","details":"Marooned Ben Gunn in Treasure Island dreams for years of one thing above treasure: a bite of toasted cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Treasure-island02.png?width=1024"},{"name":"Bleu d'Auvergne","rarity":"rare","id":"bleu-d-auvergne","subtitle":"Variety","details":"French cow's-milk blue, creamy and less salty than Roquefort, with a spicy mould bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wikicheese%20Clermont-Ferrand%20-%20Bleu%20d%27Auvergne%2020220825-02.jpg?width=1024"},{"name":"Bra Cheese Festival","rarity":"rare","id":"bra-cheese-festival","subtitle":"Lore","details":"Slow Food's great cheese gathering fills Bra, Italy, with rare farmhouse cheeses from herders and makers worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bra-panorama.jpg?width=1024"},{"name":"Brillat-Savarin","rarity":"rare","id":"brillat-savarin","subtitle":"Variety","details":"French triple-cream cow's-milk cheese enriched with cream; dense, buttery and delicately tangy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brillat-savarin.jpg?width=1024"},{"name":"Caciocavallo","rarity":"rare","id":"caciocavallo","subtitle":"Variety","details":"Southern Italian aged stretched-curd cheese, hung in pairs over a beam; firm and piquant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caciocavallo%20Pugliese.jpg?width=1024"},{"name":"Cantal","rarity":"rare","id":"cantal","subtitle":"Variety","details":"Ancient Auvergne cow's-milk cheese, firm and tangy; young is mild, aged turns strong and crumbly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cantal%2006.jpg?width=1024"},{"name":"Casein","rarity":"rare","id":"casein","subtitle":"Making","details":"Casein is milk's main protein; rennet makes casein molecules link into a network that traps fat and water as curd.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Joehrerhof%20Schafkaeseproduktion%20Abtrennen%20der%20Molke%2013062014%20775.jpg?width=1024"},{"name":"Chaource","rarity":"rare","id":"chaource","subtitle":"Variety","details":"Champagne cow's-milk cheese with a bloomy rind, chalky core and mushroomy, creamy finish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chaource%20%28fromage%29%2009.jpg?width=1024"},{"name":"Cheese Dome","rarity":"rare","id":"cheese-dome","subtitle":"Serving","details":"A glass or wooden dome traps humidity around a cheese, protecting its aroma while keeping it from drying out.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%A4seglocke.jpg?width=1024"},{"name":"Cheese on the Oregon Trail","rarity":"rare","id":"cheese-on-the-oregon-trail","subtitle":"Lore","details":"Firm, well-aged cheese travelled well in wagon stores: dense, filling food that kept far better than soft cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oregon%20National%20Historic%20Trail%20in%20Wyoming.jpg?width=1024"},{"name":"Cheese Plane","rarity":"rare","id":"cheese-plane","subtitle":"Serving","details":"A flat Norwegian ostehøvel shaves even thin slices from firm cheese with a single steady pull.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20planes.jpg?width=1024"},{"name":"Cheese Soufflé","rarity":"rare","id":"cheese-souffle","subtitle":"Dish","details":"A baked egg dish puffed with cheese that rises dramatically and is served straight from the oven.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Souffl%C3%A9.JPG?width=1024"},{"name":"Cheese Straws","rarity":"rare","id":"cheese-straws","subtitle":"Dish","details":"Crisp pastry twists baked with sharp cheese and a little spice until flaky and golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Straw%20-%20GAIL%27s%20Bakery%202025-12-21.jpg?width=1024"},{"name":"Cheese Trier","rarity":"rare","id":"cheese-trier","subtitle":"Serving","details":"A hollow, auger-like iron pushed into a wheel to pull a plug sample — graders judge the whole wheel from that one core.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20taster%20%28AM%201932.394-2%29.jpg?width=1024"},{"name":"Curd Cutting","rarity":"rare","id":"curd-cutting","subtitle":"Making","details":"Once milk sets into curd, makers cut it into cubes; smaller cubes release more whey and produce a firmer finished cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%3B%20a%20short%20treatise%20on%20the%20manufacture%20of%20various%20kinds%20of%20domestic%20and%20foreign%20cheese%2C%20Cheddar%2C%20Dutch%2C%20Swiss%2C%20Italian%2C%20French%2C%20Limburger%2C%20Neufchatel%2C%20cream%2C%20cottage%20cheese%2C%20etc%20%281918%29%20%2820603819055%29.jpg?width=1024"},{"name":"Dutch Cheese Still Life","rarity":"rare","id":"dutch-cheese-still-life","subtitle":"Lore","details":"Dutch Golden Age painters stacked towering cheeses in still lifes as symbols of wealth, craft and quiet showing off.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clara%20Peeters%20-%20Still%20Life%20with%20Cheeses%2C%20Almonds%20and%20Pretzels.jpg?width=1024"},{"name":"Esrom","rarity":"rare","id":"esrom","subtitle":"Variety","details":"Danish cow's-milk washed-rind cheese, rectangular and pungent, with a soft golden paste.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Esrom.jpg?width=1024"},{"name":"Fonduta","rarity":"rare","id":"fonduta","subtitle":"Dish","details":"An Italian melted Fontina dish enriched with egg yolks and milk and often spooned over food.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Full%20cheese%20fondue%20set%20-%20in%20Switzerland.JPG?width=1024"},{"name":"Fourme d'Ambert","rarity":"rare","id":"fourme-d-ambert","subtitle":"Variety","details":"One of France's oldest blues: tall, mild cow's-milk cylinders with a smooth, creamy paste.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fourme%20d%27Ambert%2004.jpg?width=1024"},{"name":"Gougères","rarity":"rare","id":"gougeres","subtitle":"Dish","details":"French choux pastry puffs baked with Gruyère cheese until hollow and crisp outside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gougeres%20-%20Cheese%20Puffs%20-%20Dinner%20at%20Central%20Michel%20Richard%20-%20Washington%20DC%20-%20United%20States%20Capital%20-%20October%202010%20%285132730153%29.jpg?width=1024"},{"name":"Graviera","rarity":"rare","id":"graviera","subtitle":"Variety","details":"Greek hard cheese, mostly sheep's milk, sweet and nutty; a favourite table and grating cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Graviera%20Kritis%20Kraounaki%20Rethymnou.jpg?width=1024"},{"name":"Idiazabal","rarity":"rare","id":"idiazabal","subtitle":"Variety","details":"Basque sheep's-milk cheese, often lightly smoked; compact, tangy and savoury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queso%20Idiaz%C3%A1bal.jpg?width=1024"},{"name":"Jackson's Big Block of Cheese","rarity":"rare","id":"jacksons-big-block-of-cheese","subtitle":"Lore","details":"A 1,400-pound cheese aged in the White House until President Jackson finally served it to a hungry public crowd in 1837.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20corner%20of%20the%20East%20Room%2C%20White%20House%20LCCN2006680305.jpg?width=1024"},{"name":"Jefferson's Mammoth Cheese","rarity":"rare","id":"jeffersons-mammoth-cheese","subtitle":"Lore","details":"In 1802, Massachusetts Baptists sent President Jefferson a 1,235-pound 'mammoth cheese' inscribed with a political motto.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chesire%20Cheese%20Monument%20Chesire%20MA%20USA%20Sep%202012.jpg?width=1024"},{"name":"Kasseri","rarity":"rare","id":"kasseri","subtitle":"Variety","details":"Greek stretched-curd sheep's-milk cheese, springy and mild, used for the flaming saganaki pan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kasseri%20Leveti%20AB.jpg?width=1024"},{"name":"Laguiole","rarity":"rare","id":"laguiole","subtitle":"Variety","details":"Aubrac cow's-milk cheese aged for months to years; dense, lactic and gently piquant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Laguiole%20%28cheese%29.jpg?width=1024"},{"name":"Langres","rarity":"rare","id":"langres","subtitle":"Variety","details":"Champagne cow's-milk cheese with a sunken top made for a splash of local spirit; soft and tangy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Langres%20fromage%20AOP%20coupe.jpg?width=1024"},{"name":"Livarot","rarity":"rare","id":"livarot","subtitle":"Variety","details":"Normandy cow's-milk cheese bound with sedge bands, nicknamed the Colonel for its stripes; strong and spicy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Livarot%20%28fromage%29%2011.jpg?width=1024"},{"name":"Mahón","rarity":"rare","id":"mahon","subtitle":"Variety","details":"Menorcan cow's-milk cheese, orange-rinded and firm, with a salty, lactic tang from sea air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Formatge%20Ma%C3%B3%20artes%C3%A0.jpg?width=1024"},{"name":"Milling","rarity":"rare","id":"milling","subtitle":"Making","details":"Milling breaks drained curd into small pieces before salting and pressing, giving milled-curd cheeses their crumbly, open texture.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheddar%20cheese%20making%20%281893%29%20%2820417150609%29.jpg?width=1024"},{"name":"Mimolette","rarity":"rare","id":"mimolette","subtitle":"Variety","details":"French cow's-milk cheese coloured deep orange, aged until hard and caramel-nutty; its rind is pitted by mites.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mimolette%20vieille%20etuvee.jpg?width=1024"},{"name":"Mozzarella Sticks","rarity":"rare","id":"mozzarella-sticks","subtitle":"Dish","details":"Breaded mozzarella fried until the coating crisps and the centre turns soft and stretchy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fried%20Mozzarella%20Sticks%20at%20Millers%20Pub%20%28301456962%29.jpg?width=1024"},{"name":"Neufchâtel","rarity":"rare","id":"neufchatel","subtitle":"Variety","details":"Norman cow's-milk cheese, often heart-shaped, with a bloomy rind and grainy, salty centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neufchatel%202.jpg?width=1024"},{"name":"Nose to Rind","rarity":"rare","id":"nose-to-rind","subtitle":"Serving","details":"Cutting each wedge from centre to rind gives every serving a taste of every stage of ripening in one piece.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue%20Stilton%2001.jpg?width=1024"},{"name":"Nottingham Cheese Riot","rarity":"rare","id":"nottingham-cheese-riot","subtitle":"Lore","details":"In 1766, Nottingham crowds protesting food prices seized cheeses at the Goose Fair and rolled them through the streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nottingham%20MMB%2075%20Market%20Square.jpg?width=1024"},{"name":"Ossau-Iraty","rarity":"rare","id":"ossau-iraty","subtitle":"Variety","details":"Basque-Béarnaise sheep's-milk cheese, firm and buttery with nutty, olive-like notes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ossau-Iraty.jpg?width=1024"},{"name":"Pasteurization","rarity":"rare","id":"pasteurization","subtitle":"Making","details":"Pasteurization heats milk briefly to kill harmful bacteria; it also gives makers a cleaner, more predictable start for cultures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Management%20of%20dairy%20plants%20%281921%29%20%2814781377235%29.jpg?width=1024"},{"name":"Penicillium Camemberti","rarity":"rare","id":"penicillium-camemberti","subtitle":"Making","details":"This white mould grows on the surface of soft cheeses, forming a bloomy rind and ripening the paste from the outside in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20text-book%20of%20mycology%20and%20plant%20pathology%20%281917%29%20%2814765182332%29.jpg?width=1024"},{"name":"Pont-l'Évêque","rarity":"rare","id":"pont-l-eveque","subtitle":"Variety","details":"Norman cow's-milk square with a washed rind, soft centre and pungent farmyard aroma.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Petit%20pont-l%27%C3%A9v%C3%AAque.jpg?width=1024"},{"name":"Port Salut","rarity":"rare","id":"port-salut","subtitle":"Variety","details":"French cow's-milk cheese created by Trappist monks; orange rind, mild and buttery paste.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Port%20Salut%20cheese.jpg?width=1024"},{"name":"Pão de Queijo","rarity":"rare","id":"pao-de-queijo","subtitle":"Dish","details":"Brazilian cheese rolls made with cassava flour that bake up puffy with a chewy centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pao%20de%20queijo%20brasil.jpg?width=1024"},{"name":"Queso Ibérico","rarity":"rare","id":"queso-iberico","subtitle":"Variety","details":"Spanish mixed-milk cheese of cow, sheep and goat; firm, oily-rich and balanced in tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pan%2C%20queso%20y%20embutido%20ib%C3%A9rico%20-%20Mumum%C3%ADo.jpg?width=1024"},{"name":"Raclette Grill","rarity":"rare","id":"raclette-grill","subtitle":"Serving","details":"A tabletop grill melts a half wheel's cut face under a heating element ready to be scraped onto the plate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Raclette%20006.jpg?width=1024"},{"name":"Roncal","rarity":"rare","id":"roncal","subtitle":"Variety","details":"Navarre sheep's-milk cheese, hard and rustic with a sharp, nutty flavour from mountain milk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queso%20roncal.jpg?width=1024"},{"name":"Saint-Nectaire","rarity":"rare","id":"saint-nectaire","subtitle":"Variety","details":"Auvergne farmhouse cow's-milk cheese with a grey-brown rind and supple, hazelnut-scented paste.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saint-Nectaire.jpg?width=1024"},{"name":"Scamorza","rarity":"rare","id":"scamorza","subtitle":"Variety","details":"Italian cow's-milk stretched cheese, often smoked; pear-shaped from being hung to dry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scamorza%20sicilian.jpg?width=1024"},{"name":"Sirnica","rarity":"rare","id":"sirnica","subtitle":"Dish","details":"A Bosnian rolled phyllo pie filled with fresh cheese and baked in a distinctive spiral shape.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sirnica%20%28Burek%29.JPG?width=1024"},{"name":"Smoking","rarity":"rare","id":"smoking","subtitle":"Making","details":"Smoking cheese over wood adds deep colour and savoury flavour; the cheese is usually cold-smoked so it flavours without melting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Smoking%20ostiepok.jpg?width=1024"},{"name":"Tequeños","rarity":"rare","id":"tequenos","subtitle":"Dish","details":"Venezuelan fried pastry sticks wrapped around salty white cheese and served as a snack.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Teque%C3%B1os%20Venezolanos.jpg?width=1024"},{"name":"The Cheese Caveau","rarity":"rare","id":"the-cheese-caveau","subtitle":"Serving","details":"A small, cool cellar or cabinet where wheels rest at cellar temperature and humidity before they are served.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Aging%20Cave.jpg?width=1024"},{"name":"The Cheese Well","rarity":"rare","id":"the-cheese-well","subtitle":"Serving","details":"Before fridges, some farms kept cheese in a cheese well: a cool stone chamber over a spring where wheels stayed chilled and aired.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Cheese%20Well%20-%20geograph.org.uk%20-%201282881.jpg?width=1024"},{"name":"The Fromager","rarity":"rare","id":"the-fromager","subtitle":"Serving","details":"The specialist who selects, ages and serves cheese, matching each wheel's ripeness to the moment it is cut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fromager%20Barth%C3%A9lemy.jpg?width=1024"},{"name":"The Great Cheese Heists","rarity":"rare","id":"the-great-cheese-heists","subtitle":"Lore","details":"Aged wheels are valuable, portable and hard to trace, which makes fine cheese a surprisingly tempting target for thieves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Warehouse%20in%20Armenia.jpg?width=1024"},{"name":"The Mammoth Cheese","rarity":"rare","id":"the-mammoth-cheese","subtitle":"Lore","details":"In 1893, Canadian makers pressed a cheddar of some 22,000 pounds and shipped it to the Chicago world fair as a national showpiece.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E2%80%9CThe%20Mammoth%20Cheese%E2%80%9D%20leaving%20Perth%2C%20Ontario%2C%20en%20route%20to%20the%20World%27s%20Columbian%20Exposition%2C%20Chicago%2C%20Illinois%20Le%20%C2%AB%20fromage%20mammouth%20%C2%BB%20quitte%20Perth%20%28Ontario%29%20%2839311927194%29.jpg?width=1024"},{"name":"Tilsit","rarity":"rare","id":"tilsit","subtitle":"Variety","details":"Swiss-German cow's-milk cheese with small holes and a washed rind; semi-firm and tangy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tilsit%20cheese.jpg?width=1024"},{"name":"Tiropita","rarity":"rare","id":"tiropita","subtitle":"Dish","details":"Greek phyllo parcels filled with feta and other cheeses and baked until crisp and flaky.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tiropita%20Greek%20dish.jpg?width=1024"},{"name":"Tomme de Savoie","rarity":"rare","id":"tomme-de-savoie","subtitle":"Variety","details":"Savoy cow's-milk tomme with a rustic grey rind, semi-firm paste and mild, cellar-earth aroma.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WikiCheese%20-%20Tomme%20de%20Savoie%20-%2020150619%20-%20002.jpg?width=1024"},{"name":"Waxed Wheel","rarity":"rare","id":"waxed-wheel","subtitle":"Serving","details":"A coat of wax seals a wheel against drying and mould, and gives cheeses like Edam their unmistakable smooth shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Y%20Fenni%20Cheese%20I.jpg?width=1024"},{"name":"Waxing","rarity":"rare","id":"waxing","subtitle":"Making","details":"A coat of wax seals a wheel against drying and mould, letting it age evenly; the bright wax also makes wheels easy to spot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wax%20for%20cheese.jpg?width=1024"},{"name":"Akkawi","rarity":"uncommon","id":"akkawi","subtitle":"Variety","details":"Levantine brined white cheese, mild and springy, often soaked to tame its salt.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D8%AB%D9%84%D8%A7%D8%AB%D8%A9%20%D8%A3%D9%86%D9%88%D8%A7%D8%B9%20%D8%AC%D8%A8%D9%86%20%D8%B9%D8%B1%D8%A8%D9%8A%D8%A9.jpg?width=1024"},{"name":"Ash Rind","rarity":"uncommon","id":"ash-rind","subtitle":"Serving","details":"A dusting of ash once protected young cheeses and alkaline ash still mellows the surface of goat cheeses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Cendrillon%20Alexis%20de%20Portneuf.jpg?width=1024"},{"name":"Ash Ripening","rarity":"uncommon","id":"ash-ripening","subtitle":"Making","details":"A dusting of food-grade ash neutralises a young cheese's acidic surface, helping a smooth, wrinkly rind grow over it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morbier.jpg?width=1024"},{"name":"Baked Brie","rarity":"uncommon","id":"baked-brie","subtitle":"Dish","details":"A wheel of Brie warmed until soft and flowing often served with fruit preserves and crackers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brie%20on%20roasted%20potatoes%20-%20Massachusetts.jpg?width=1024"},{"name":"Baked Camembert","rarity":"uncommon","id":"baked-camembert","subtitle":"Dish","details":"A whole Camembert baked in its box until molten in the centre and ready for dipping bread.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baked%20Camembert%20with%20Black%20Truffle%20slices.jpg?width=1024"},{"name":"Banon","rarity":"uncommon","id":"banon","subtitle":"Variety","details":"Provençal goat cheese wrapped in chestnut leaves; soft, woody and gently pungent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banon%2002.jpg?width=1024"},{"name":"Bel Paese","rarity":"uncommon","id":"bel-paese","subtitle":"Variety","details":"Italian cow's-milk cheese created in Lombardy; mild, buttery and made to melt smoothly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bel%20Paese%20Cheese.jpg?width=1024"},{"name":"Bitto","rarity":"uncommon","id":"bitto","subtitle":"Variety","details":"Lombard Alpine cheese of cow's milk with a little goat; aged wheels turn hard and sweet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bitto%20cheese.jpg?width=1024"},{"name":"Brocciu","rarity":"uncommon","id":"brocciu","subtitle":"Variety","details":"Corsican whey cheese from sheep or goat milk, fresh and milky, used in sweet and savoury dishes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brocciu%20passu.jpg?width=1024"},{"name":"Brunost","rarity":"uncommon","id":"brunost","subtitle":"Variety","details":"Norwegian brown whey cheese, caramel-sweet and fudge-like, sliced thin with a cheese plane.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brunost%20-%20Brown%20cheese.jpg?width=1024"},{"name":"Bryndza","rarity":"uncommon","id":"bryndza","subtitle":"Variety","details":"Slovak sheep's-milk brined cheese, soft, salty and spreadable; central to many dumpling dishes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bryndza%20cheese.jpg?width=1024"},{"name":"Cabrales","rarity":"uncommon","id":"cabrales","subtitle":"Variety","details":"Spanish blue from Asturias, mixed milks, cave-ripened and fiercely spicy-creamy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Madrid%20-%20Queso%20de%20Cabrales%20y%20Pic%C3%B3n%20Asturiano.jpg?width=1024"},{"name":"Caerphilly","rarity":"uncommon","id":"caerphilly","subtitle":"Variety","details":"Welsh cow's-milk cheese, crumbly and lemony, once a miner's lunch cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caerphilly%20cheese.jpg?width=1024"},{"name":"Canastra","rarity":"uncommon","id":"canastra","subtitle":"Variety","details":"Brazilian Minas cheese from raw cow's milk, semi-hard and tangy, aged on wooden shelves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queijo%20canastra%2C%20Minas%20Gerais.jpg?width=1024"},{"name":"Castelmagno","rarity":"uncommon","id":"castelmagno","subtitle":"Variety","details":"Piedmont cow's-milk cheese, ancient and crumbly, developing natural blue veins with age.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castelmagno%20%28formaggio%29.jpg?width=1024"},{"name":"Chalk and Cheese","rarity":"uncommon","id":"chalk-and-cheese","subtitle":"Lore","details":"British speakers call two unlike things 'chalk and cheese', a pairing in use since the Middle Ages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chalk%20and%20Cheese%2C%20Maiden%20Newton%20-%20geograph.org.uk%20-%205892475.jpg?width=1024"},{"name":"Cheese and Onion Pie","rarity":"uncommon","id":"cheese-onion-pie","subtitle":"Dish","details":"A British savoury pie filled with cheese and onions baked inside a pastry crust.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caramelized%20onion%20pie.jpg?width=1024"},{"name":"Cheese and Pickle Sandwich","rarity":"uncommon","id":"cheese-and-pickle-sandwich","subtitle":"Dish","details":"A British classic: sharp cheddar and tangy pickle chutney in plain white bread. Lunchbox royalty, no cooking required.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20and%20Pickle%20Sandwich%20Step%204%20%288576760021%29.jpg?width=1024"},{"name":"Cheese Before Dessert","rarity":"uncommon","id":"cheese-before-dessert","subtitle":"Lore","details":"French order puts cheese before dessert; the British traditionally serve it after — a friendly table argument with no winner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20course%20%289529849459%29.jpg?width=1024"},{"name":"Cheese Blintzes","rarity":"uncommon","id":"cheese-blintzes","subtitle":"Dish","details":"Thin pancakes folded around sweetened soft cheese and pan-fried until lightly golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20blintzes%20with%20blackberries.jpg?width=1024"},{"name":"Cheese Börek","rarity":"uncommon","id":"cheese-borek","subtitle":"Dish","details":"Turkish flaky pastry layered with white cheese and herbs, baked in trays or coiled into spirals and sliced warm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Muska%20B%C3%B6rek.jpg?width=1024"},{"name":"Cheese Empanadas","rarity":"uncommon","id":"cheese-empanadas","subtitle":"Dish","details":"Fried or baked pastry turnovers filled with cheese found across Latin America in many forms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20plate%20with%20six%20oven-baked%20Argentine%20ham%20and%20cheese%20empanadas.jpg?width=1024"},{"name":"Cheese Fork","rarity":"uncommon","id":"cheese-fork","subtitle":"Serving","details":"A two-pronged fork steadies a wedge on the board while another knife cuts keeping hands clear of the blade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palais-Niel%20couverts.JPG?width=1024"},{"name":"Cheese Lyre","rarity":"uncommon","id":"cheese-lyre","subtitle":"Serving","details":"A wire strung across a frame, the lyre portions soft cheeses into neat, even slices with one downward press.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%3B%20a%20short%20treatise%20on%20the%20manufacture%20of%20various%20kinds%20of%20domestic%20and%20foreign%20cheese%2C%20Cheddar%2C%20Dutch%2C%20Swiss%2C%20Italian%2C%20French%2C%20Limburger%2C%20Neufchatel%2C%20cream%2C%20cottage%20cheese%2C%20etc%20%281918%29%20%2820603847215%29.jpg?width=1024"},{"name":"Cheese Quesadilla","rarity":"uncommon","id":"cheese-quesadilla","subtitle":"Dish","details":"A tortilla folded around melted cheese and griddled until the outside turns crisp and golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Quesadilla%202.jpg?width=1024"},{"name":"Cheese Scones","rarity":"uncommon","id":"cheese-scones","subtitle":"Dish","details":"Savoury scones baked with grated cheese in the dough and often served warm with butter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Swedish%20cheese%20scones.jpg?width=1024"},{"name":"Cheese Wedding Cake","rarity":"uncommon","id":"cheese-wedding-cake","subtitle":"Lore","details":"Some couples swap sponge for stacked whole wheels, cut like a cake and served as the evening cheese course.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh%20Townscape%20%2C%20Cheese%20Wedding%20Cakes%20Service%20at%20Kerr%20Street%20-%20geograph.org.uk%20-%202423612.jpg?width=1024"},{"name":"Cheesefare Week","rarity":"uncommon","id":"cheesefare-week","subtitle":"Lore","details":"In Orthodox tradition, Cheesefare Week is the last week before Lent, when meat is set aside but dairy still fills the table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maslenitsa%20kustodiev.jpg?width=1024"},{"name":"Cheeses Named for Places","rarity":"uncommon","id":"cheeses-named-for-places","subtitle":"Lore","details":"Cheddar, Gouda, Parmesan and Brie all carry place names: geography you can taste on a cheese board.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kefalotyri.jpg?width=1024"},{"name":"Cheshire","rarity":"uncommon","id":"cheshire","subtitle":"Variety","details":"English cow's-milk cheese, crumbly and salty with a long history as a cooking cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheshire%20Cheese.jpg?width=1024"},{"name":"Chhurpi","rarity":"uncommon","id":"chhurpi","subtitle":"Variety","details":"Himalayan yak or cow cheese dried rock-hard for chewing, or kept soft for soups and curries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chhurpi.jpg?width=1024"},{"name":"Chile con Queso","rarity":"uncommon","id":"chile-con-queso","subtitle":"Dish","details":"A Tex-Mex dip of melted cheese blended with chillies and served warm with tortilla chips.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr%20etee%203648986444--Felix-style%20chile%20con%20queso.jpg?width=1024"},{"name":"Creamery","rarity":"uncommon","id":"creamery","subtitle":"Making","details":"A creamery is where milk becomes cheese, butter, and cream, from small farmstead rooms to large halls of steel vats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USDA%20RD%20RBCS%20Administrator%20Gimmie%20Jo%20Jansonius%20welcomed%20by%20Harmony%20Valley%20Farm%20and%20Westby%20Cooperative%20CreameryCreamery%20%2820261008-USDA-RD-ACI-0420%29.jpg?width=1024"},{"name":"Crottin de Chavignol","rarity":"uncommon","id":"crottin-de-chavignol","subtitle":"Variety","details":"Loire goat's-milk buttons that grow firmer and stronger as they age; nutty and dense.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crottin%20de%20Chavignol.jpg?width=1024"},{"name":"Danish Blue","rarity":"uncommon","id":"danish-blue","subtitle":"Variety","details":"Danish cow's-milk blue, sharp and salty with a creamy bite, made as a Roquefort alternative.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Danish%20Blue%20cheese.jpg?width=1024"},{"name":"Double Gloucester","rarity":"uncommon","id":"double-gloucester","subtitle":"Variety","details":"English cow's-milk cheese, orange and firm, rolled downhill in the famous cheese-rolling race.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%2024%20bg%20051306.jpg?width=1024"},{"name":"Draining","rarity":"uncommon","id":"draining","subtitle":"Making","details":"Draining lets whey run from cut curd through cloth, mats, or moulds; how long it drains decides how soft the cheese stays.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fresh%20chevre%20hanging%20in%20a%20farmstead%20dairy.jpg?width=1024"},{"name":"Frico","rarity":"uncommon","id":"frico","subtitle":"Dish","details":"An Italian crisp made by frying grated Montasio or Parmesan until lacy and golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fricotenero.jpg?width=1024"},{"name":"Gamalost","rarity":"uncommon","id":"gamalost","subtitle":"Variety","details":"Norwegian skim-milk cheese ripened with mould, dense, sharp and famously strong.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gamalost-NorwegianOldCheese.jpg?width=1024"},{"name":"Garrotxa","rarity":"uncommon","id":"garrotxa","subtitle":"Variety","details":"Catalan goat's-milk cheese with a grey rind, firm paste and mild, nutty flavour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Un%20formatge%20IGP%20Formatge%20Garrotxa%20%2831-07-2024%29.jpg?width=1024"},{"name":"Goat Cheese & Honey","rarity":"uncommon","id":"goat-cheese-and-honey","subtitle":"Dish","details":"Fresh goat cheese drizzled with honey: the salt and tang of the cheese against floral sweetness, a pairing as old as both.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Formaggio%20crudo%20di%20capra%20e%20miele.jpg?width=1024"},{"name":"Gorgonzola Dolce","rarity":"uncommon","id":"gorgonzola-dolce","subtitle":"Variety","details":"The sweet, spoonable style of Italian blue: cow's milk, creamy and mildly spiced by mould.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20big%20blue%20cheese.jpg?width=1024"},{"name":"Gouda Cheese Market","rarity":"uncommon","id":"gouda-cheese-market","subtitle":"Lore","details":"Golden wheels are stacked in Gouda's square while buyers and sellers still seal bargains with a ritual hand-clap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prima%20donna%20-%20Limonaire%20Fr%C3%A8res%20street%20organ%20fet%20Zonnetje%20%28owned%20by%20A.%20Vergeer%2C%20Gouda%29%20-%20Gouda%20Cheese%20Market%2C%20Gouda%2C%20the%20Netherlands%2C%202014-11-03.jpg?width=1024"},{"name":"Hard Cheese Knife","rarity":"uncommon","id":"hard-cheese-knife","subtitle":"Serving","details":"A heavy sharp-edged blade with a raised handle gives the leverage needed to cut through dense aged wheels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tagliagrana.jpg?width=1024"},{"name":"Kanafeh","rarity":"uncommon","id":"kanafeh","subtitle":"Dish","details":"A Levantine dessert of shredded pastry and soft cheese soaked in syrup and topped with pistachio.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Kanafeh.jpg?width=1024"},{"name":"Kashkaval","rarity":"uncommon","id":"kashkaval","subtitle":"Variety","details":"Balkan sheep or cow cheese, semi-hard and yellow, stretched and salted like a cousin of Caciocavallo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kashkaval%20Albania.jpg?width=1024"},{"name":"Lactose","rarity":"uncommon","id":"lactose","subtitle":"Making","details":"Lactose is milk's natural sugar; starter bacteria ferment it into lactic acid, and long-aged cheeses end up with almost none left.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20person%20is%20pouring%20white%20milk%20into%20a%20glass%20cup.jpg?width=1024"},{"name":"Lancashire","rarity":"uncommon","id":"lancashire","subtitle":"Variety","details":"English cow's-milk cheese; creamy when young, crumbly and sharp when aged.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lancashire%20cheese.jpg?width=1024"},{"name":"Leerdammer","rarity":"uncommon","id":"leerdammer","subtitle":"Variety","details":"Dutch cow's-milk cheese with holes, mild and nutty, developed as a cross of Emmental and Gouda styles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leerdammer%20kaas.jpg?width=1024"},{"name":"Leipäjuusto","rarity":"uncommon","id":"leipajuusto","subtitle":"Variety","details":"Finnish squeaky cheese baked until spotted, made from cow's colostrum-rich milk or plain milk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leip%C3%A4juusto%20cheese%20with%20cloudberry%20jam.jpg?width=1024"},{"name":"Maasdam","rarity":"uncommon","id":"maasdam","subtitle":"Variety","details":"Dutch cow's-milk cheese with big holes and a sweet, nutty taste, made in Emmental style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maasdam-cheese.jpg?width=1024"},{"name":"Maroilles","rarity":"uncommon","id":"maroilles","subtitle":"Variety","details":"Northern French cow's-milk washed-rind square, strong-smelling with a soft, savoury heart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jielbeaumadier%20chicon%20au%20jambon%20maroilles%202010.jpg?width=1024"},{"name":"Mbejú","rarity":"uncommon","id":"mbeju","subtitle":"Dish","details":"A Paraguayan flatbread of cassava starch and queso Paraguay, fried crisp at the edges and soft and cheesy inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mbeju%20and%20cocido.jpg?width=1024"},{"name":"Membrillo & Manchego","rarity":"uncommon","id":"membrillo-manchego","subtitle":"Dish","details":"A Spanish pairing of firm sheep cheese with sweet quince paste served in neat slices.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queso%20Manchego%20con%20Membrillo%20%283578359194%29.jpg?width=1024"},{"name":"Molding","rarity":"uncommon","id":"molding","subtitle":"Making","details":"Fresh curd is ladled or packed into moulds called hoops, which drain whey and give each young cheese its final shape.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/020210606%20122149%20Set%20cheese%20molds%2C%201820%2C%20Beskids.jpg?width=1024"},{"name":"Montasio","rarity":"uncommon","id":"montasio","subtitle":"Variety","details":"Alpine cheese from Friuli and the Veneto, nutty and firm — eaten young and milky, or aged hard for grating.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Montasio%20formaggio.jpg?width=1024"},{"name":"National Cheese Day","rarity":"uncommon","id":"national-cheese-day","subtitle":"Lore","details":"June 4 is marked in the United States as National Cheese Day, an excuse that cheese lovers rarely need.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Market%20-%20geograph.org.uk%20-%204388701.jpg?width=1024"},{"name":"Natural Rind","rarity":"uncommon","id":"natural-rind","subtitle":"Serving","details":"Formed by air and time alone, a natural rind is the wheel's own dried surface, often brushed as it matures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crottin%2002.jpg?width=1024"},{"name":"Oscypek","rarity":"uncommon","id":"oscypek","subtitle":"Variety","details":"Polish smoked sheep's-milk cheese from the Tatras, spindle-shaped and decorated by wooden moulds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oscypki.jpg?width=1024"},{"name":"Paneer","rarity":"uncommon","id":"paneer","subtitle":"Variety","details":"South Asian fresh cow or buffalo cheese set with acid, firm enough to fry and never melting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panir%20Paneer%20Indian%20cheese%20fresh.jpg?width=1024"},{"name":"Parmesan Knife","rarity":"uncommon","id":"parmesan-knife","subtitle":"Serving","details":"Short, stubby and almond-bladed, this knife pries Parmesan apart along its crystals instead of slicing it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Parmesan%20cheese%20knife%20on%20block%20of%20cheese.jpg?width=1024"},{"name":"Paxton & Whitfield","rarity":"uncommon","id":"paxton-and-whitfield","subtitle":"Lore","details":"London cheesemongers trading since 1797 and long holders of royal warrants — the shop that supplies the palace's cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheesemonger%20Paxton%20%26%20Whitfield%20on%20Jermyn%20Street%20in%20London.JPG?width=1024"},{"name":"Pecorino Toscano","rarity":"uncommon","id":"pecorino-toscano","subtitle":"Variety","details":"Tuscan sheep's-milk cheese, younger and gentler than Romano; firm, sweet and herbal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pecorino%20Toscano%20DOP.JPG?width=1024"},{"name":"Piercing","rarity":"uncommon","id":"piercing","subtitle":"Making","details":"Blue cheeses are pierced with needles so air can reach the mould inside, letting blue veins spread through the wheel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue%20Stilton%20Penicillium.jpg?width=1024"},{"name":"Pressing","rarity":"uncommon","id":"pressing","subtitle":"Making","details":"Pressing squeezes whey from curd packed in moulds, knitting the pieces into a solid wheel that can be aged and cut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20manufacture%20of%20neufch%C3%A2tel%20and%20cream%20cheese%20in%20the%20factory%20%281918%29%20%2814781832374%29.jpg?width=1024"},{"name":"Robiola","rarity":"uncommon","id":"robiola","subtitle":"Variety","details":"Piedmont soft cheese of mixed milks, rindless or bloomy, tangy and spreadable.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Robiola%20di%20Roccaverano.jpg?width=1024"},{"name":"Roquefort Shepherd Legend","rarity":"uncommon","id":"roquefort-shepherd-legend","subtitle":"Lore","details":"Legend says a shepherd left bread and ewe's cheese in a cave, returned months later, and found the first Roquefort.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roquefort%205.jpg?width=1024"},{"name":"Sainte-Maure de Touraine","rarity":"uncommon","id":"sainte-maure-de-touraine","subtitle":"Variety","details":"Loire goat cheese rolled in ash with a straw through its centre; dense and lemony.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sainte-Maure%20de%20touraine%2007.jpg?width=1024"},{"name":"Salting","rarity":"uncommon","id":"salting","subtitle":"Making","details":"Salt may be mixed into milled curd, rubbed on rinds, or added by brining; it controls moisture, microbes, and flavour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20science%20and%20practice%20of%20cheese-making%3B%20a%20treatise%20on%20the%20manufacture%20of%20American%20Cheddar%20cheese%20and%20other%20varieties%2C%20intended%20as%20a%20text-book%20for%20the%20use%20of%20dairy%20teachers%20and%20students%20in%20classroom%20%2814770911034%29.jpg?width=1024"},{"name":"Sbrinz","rarity":"uncommon","id":"sbrinz","subtitle":"Variety","details":"Swiss extra-hard cow's-milk cheese, aged for years and grated or broken like Parmesan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sbrinz.jpg?width=1024"},{"name":"Serra da Estrela","rarity":"uncommon","id":"serra-da-estrela","subtitle":"Variety","details":"Portuguese sheep's-milk cheese from Serra da Estrela, soft and spoonable when young, thistle-rennet set.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queijo%20Serra%20da%20Estrela.jpg?width=1024"},{"name":"Shanklish","rarity":"uncommon","id":"shanklish","subtitle":"Variety","details":"Levantine aged cheese balls rolled in spices and herbs; crumbly, sharp and pungent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shanklish%20cheese%20balls.jpg?width=1024"},{"name":"Shropshire Blue","rarity":"uncommon","id":"shropshire-blue","subtitle":"Variety","details":"English blue cow's-milk cheese coloured orange with annatto; mellow and creamy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shropshire%20Blue.jpg?width=1024"},{"name":"Slate Cheese Board","rarity":"uncommon","id":"slate-cheese-board","subtitle":"Serving","details":"Dark slate keeps a cool surface for serving and takes chalk labels directly beside each cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheeseboard%20platter%20at%20Black%20Horse%20Inn%2C%20Nuthurst%2C%20West%20Sussex%2C%20England.jpg?width=1024"},{"name":"Soft Cheese Knife","rarity":"uncommon","id":"soft-cheese-knife","subtitle":"Serving","details":"Holes or a thin forked blade stop soft cheese from sticking, so a ripe slice lands intact on the plate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philly%20cream%20cheese.jpg?width=1024"},{"name":"Sottocenere","rarity":"uncommon","id":"sottocenere","subtitle":"Variety","details":"Italian cow's-milk cheese ripened under ash with truffle and spices; firm and aromatic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sottocenere%20al%20Tartufo.jpg?width=1024"},{"name":"Stilton at Christmas","rarity":"uncommon","id":"stilton-at-christmas","subtitle":"Lore","details":"In Britain, a pot of blue Stilton with a splash of port is a Christmas table ritual dating back generations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-2019-12-25%20Stilton%20Cheese%20puff%20pastry%20pocket%2C%20Sheringham.JPG?width=1024"},{"name":"Stracchino","rarity":"uncommon","id":"stracchino","subtitle":"Variety","details":"Lombard cow's-milk soft cheese, creamy and mild, also called Crescenza for its growth in richness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stracchino.jpg?width=1024"},{"name":"Stretching Curd","rarity":"uncommon","id":"stretching-curd","subtitle":"Making","details":"Pasta filata curd is stretched in hot water until it turns smooth and elastic, the technique behind stringy, pull-apart cheeses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/01%20Queso%20Mexicano%20Oaxaca.jpg?width=1024"},{"name":"Syrniki","rarity":"uncommon","id":"syrniki","subtitle":"Dish","details":"Pan-fried curd cheese patties from Eastern Europe made with tvorog and served with sour cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Syrniki6.jpg?width=1024"},{"name":"São Jorge","rarity":"uncommon","id":"sao-jorge","subtitle":"Variety","details":"Portuguese cow's-milk cheese from the Azores, firm and peppery after long aging.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queijo%20S%C3%A3o%20Jorge%20-%204%20pcs.jpg?width=1024"},{"name":"Telemea","rarity":"uncommon","id":"telemea","subtitle":"Variety","details":"Romanian brined white cheese, usually cow or sheep milk, crumbly and salty like feta.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Telemea%20de%20oaie.jpg?width=1024"},{"name":"The Cheese Wheel","rarity":"uncommon","id":"the-cheese-wheel","subtitle":"Serving","details":"The wheel shape lets a cheese age evenly, roll to the cellar, stack for storage and be cut in fair wedges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cowgirl%20Creamery%20Point%20Reyes%20-%20Red%20Hawk%20cheese.jpg?width=1024"},{"name":"The Deli Counter","rarity":"uncommon","id":"the-deli-counter","subtitle":"Serving","details":"Glass-fronted and gleaming, the deli counter is where wheels meet the knife: cut to order, weighed, and wrapped while you watch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2016%20366%2099%20Angelo%20%2826289203556%29.jpg?width=1024"},{"name":"The Parmesan Bank","rarity":"uncommon","id":"the-parmesan-bank","subtitle":"Lore","details":"Since 1953, an Italian bank vault has stored Parmigiano Reggiano wheels as loan collateral, aging the security until it pays.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Punch%20%281841%29%20%2814780524114%29.jpg?width=1024"},{"name":"The Sharing Board","rarity":"uncommon","id":"the-sharing-board","subtitle":"Serving","details":"One big board, everything on it: wedges, grapes, bread and chutney in the middle of the table, and everyone reaching in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20platter%2C%20french%20style%20%2842231088730%29.jpg?width=1024"},{"name":"The Truckle","rarity":"uncommon","id":"the-truckle","subtitle":"Serving","details":"A small, barrel-shaped wheel, traditionally a miniature of a larger farmhouse cheese and sized for one household.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Montgomery%27s%20Cheddar%20lors%20du%20WikiCheese%2001.jpg?width=1024"},{"name":"Torta del Casar","rarity":"uncommon","id":"torta-del-casar","subtitle":"Variety","details":"Spanish sheep's-milk cheese with a soft, spoonable centre and bitter-herb rennet tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Torta%20del%20Casar%20DOP.jpg?width=1024"},{"name":"Turning","rarity":"uncommon","id":"turning","subtitle":"Making","details":"Aging wheels are turned regularly so moisture and fat stay even, rinds develop on all sides, and no wheel slumps flat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turning%20of%20cheese%20prior%20to%20milling%20at%20the%20Tavistock%20Cheese%20Company%20%28I0004499%29.jpg?width=1024"},{"name":"Tête de Moine","rarity":"uncommon","id":"tete-de-moine","subtitle":"Variety","details":"Swiss cow's-milk cheese shaved into rosettes with a girolle; dense, fruity and aromatic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Girolle%20tete%20de%20moine.jpg?width=1024"},{"name":"Vacherin Mont d'Or","rarity":"uncommon","id":"vacherin-mont-d-or","subtitle":"Variety","details":"Seasonal cow's-milk cheese from the Jura, sold boxed in spruce and eaten soft with a spoon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vacherin%20du%20haut%20Doubs.jpg?width=1024"},{"name":"Valençay","rarity":"uncommon","id":"valencay","subtitle":"Variety","details":"Loire goat cheese shaped as a truncated pyramid and dusted with ash; fresh and tangy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Valen%C3%A7ay%2004.jpg?width=1024"},{"name":"Whey","rarity":"uncommon","id":"whey","subtitle":"Making","details":"Whey is the watery liquid left after curd forms; it is drained away, fed to animals, or cooked down into other foods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Whey%20beverage.jpg?width=1024"},{"name":"Why Swiss Cheese Has Holes","rarity":"uncommon","id":"why-swiss-cheese-has-holes","subtitle":"Lore","details":"The famous holes, called eyes, grow as bacteria release gas inside the wheel while it ages and ripens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Emmentaler%20aoc%20block.jpg?width=1024"},{"name":"Wooden Cheese Box","rarity":"uncommon","id":"wooden-cheese-box","subtitle":"Serving","details":"Thin wood boxes package soft wheels for ageing and travel, and some go straight into the oven for baking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tesco%20Camembert%20cheese%20with%20wooden%20box.jpg?width=1024"},{"name":"Ye Olde Cheshire Cheese","rarity":"uncommon","id":"ye-olde-cheshire-cheese","subtitle":"Lore","details":"This Fleet Street pub, rebuilt after the Great Fire of London, has poured ale for writers from Dickens's age onward.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ye%20Olde%20Cheshire%20Cheese%20-%20geograph.org.uk%20-%20650446.jpg?width=1024"},{"name":"A Band Named String Cheese","rarity":"common","id":"a-band-named-string-cheese","subtitle":"Lore","details":"Colorado jam band The String Cheese Incident took its name from a food fight involving string cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/String%20Cheese%20Incident.jpg?width=1024"},{"name":"Afuega'l Pitu","rarity":"common","id":"afuega-l-pitu","subtitle":"Variety","details":"Asturian cow's-milk cheese, cone-shaped, tangy and sometimes spiced with paprika.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Variedaes-afuega.jpg?width=1024"},{"name":"Aging Boards","rarity":"common","id":"aging-boards","subtitle":"Making","details":"Wooden boards line many aging shelves; they wick moisture from rinds, harbour helpful microbes, and are scrubbed between batches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Parmigiano-Reggiano%20new%20and%20old.JPG?width=1024"},{"name":"Anari","rarity":"common","id":"anari","subtitle":"Variety","details":"Cypriot whey cheese from the halloumi pot: soft and mild when fresh, or salted and dried rock-hard for grating.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anari%20Limassol.jpg?width=1024"},{"name":"Anthotyro","rarity":"common","id":"anthotyro","subtitle":"Variety","details":"Greek whey cheese, soft and snowy-white, made from sheep's or goat's whey with a little milk or cream stirred in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%CE%91%CE%BD%CE%B8%CF%8C%CF%84%CF%85%CF%81%CE%BF%CF%82.JPG?width=1024"},{"name":"Azeitão","rarity":"common","id":"azeitao","subtitle":"Variety","details":"Portuguese sheep's-milk cheese, small, soft and spoonable with a bitter-herb finish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queijo%20de%20Azeit%C3%A3o.jpg?width=1024"},{"name":"Bandel","rarity":"common","id":"bandel","subtitle":"Variety","details":"Indian cheese from West Bengal, salted, smoked and crumbly, sold in small dry discs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bandel%20Cheese%2C%20Kolkata%2C%20West%20Bengal%201.jpg?width=1024"},{"name":"Beemster","rarity":"common","id":"beemster","subtitle":"Variety","details":"North Holland's aged Gouda-style cheese, ripened until crunchy crystals form and butterscotch notes develop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beemster%20detail.jpg?width=1024"},{"name":"Bergkäse","rarity":"common","id":"bergkase","subtitle":"Variety","details":"Alpine cow's-milk mountain cheese, firm and aromatic from high-pasture milk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2014-12-08%20Bergk%C3%A4se%20Milfina%205711.jpg?width=1024"},{"name":"Boerenkaas","rarity":"common","id":"boerenkaas","subtitle":"Variety","details":"Dutch farmhouse raw-milk cheese, firmer and more complex than factory Gouda styles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dutch%20cheese.jpg?width=1024"},{"name":"British Cheese Week","rarity":"common","id":"british-cheese-week","subtitle":"Lore","details":"A week of tastings and awards each year celebrates Britain's hundreds of farmhouse and factory cheeses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Some%20particulars%20about%20dairying%20in%20the%20Netherlands%2C%20for%20the%20members%20of%20the%20British%20dairy%20farmers%20ass.%20Excursion%20May%201911%20%281911%29%20%2814804907943%29.jpg?width=1024"},{"name":"Broccoli Cheddar Soup","rarity":"common","id":"broccoli-cheddar-soup","subtitle":"Dish","details":"A creamy soup where broccoli is simmered and finished with melted cheddar cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Broccoli%20cheddar%20soup%20and%20grilled%20cheese%20sandwich.jpg?width=1024"},{"name":"Buffalo Milk","rarity":"common","id":"buffalo-milk","subtitle":"Making","details":"Water buffalo milk is very white and rich, with roughly twice the fat of cow's milk, making especially creamy fresh cheeses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milking%20the%20Buffalo%20%2835571241665%29.jpg?width=1024"},{"name":"Caciotta","rarity":"common","id":"caciotta","subtitle":"Variety","details":"Soft, mild cow's-milk cheese from central Italy, eaten fresh within days or briefly aged for a firmer bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caciotta%20marchigiana%202.jpg?width=1024"},{"name":"Cashel Blue","rarity":"common","id":"cashel-blue","subtitle":"Variety","details":"Irish cow's-milk blue, creamy and gentle, made on a farm in County Tipperary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CashelBlue.JPG?width=1024"},{"name":"Cauliflower Cheese","rarity":"common","id":"cauliflower-cheese","subtitle":"Dish","details":"A British bake of cauliflower covered in cheese sauce and grilled until bubbling on top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baked%20Cauliflower%20with%20special%20cheese%20sauce.jpg?width=1024"},{"name":"Cheese and Crackers","rarity":"common","id":"cheese-and-crackers","subtitle":"Dish","details":"A simple serving of sliced or wedged cheese with plain crackers that lets each cheese lead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20charcuterie%20board%20with%20cheese%20and%20crackers.jpg?width=1024"},{"name":"Cheese Basket","rarity":"common","id":"cheese-basket","subtitle":"Serving","details":"A woven basket carries small cheeses to market and doubles as a rustic way to bring them to the table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20market%20in%20Alkmaar%2C%201977%20%2805%29.jpg?width=1024"},{"name":"Cheese Biscuits","rarity":"common","id":"cheese-biscuits","subtitle":"Dish","details":"Flaky savoury biscuits baked with cheddar cheese worked into the dough for extra richness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Home%20made%20cheddar%20cheese%20biscuits.jpg?width=1024"},{"name":"Cheese Board","rarity":"common","id":"cheese-board","subtitle":"Serving","details":"A flat board groups cheeses for serving, traditionally ordered from mildest to strongest around the edge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Platter%20%2814362170692%29.jpg?width=1024"},{"name":"Cheese Dish","rarity":"common","id":"cheese-dish","subtitle":"Serving","details":"A covered dish keeps a portioned cheese fresh in storage and brings it neatly to the table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Covered%20Cheese%20Dish%2C%20Josiah%20Wedgwood%20and%20Sons%2C%20c.%201900%2C%20blue%20jasperware%20-%20Chazen%20Museum%20of%20Art%20-%20DSC01972.JPG?width=1024"},{"name":"Cheese Grater","rarity":"common","id":"cheese-grater","subtitle":"Serving","details":"Grating turns a hard wedge into fine shreds that melt evenly and season a dish in seconds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fine%20Microplane%20Grating%20Hard%20Cheese.jpg?width=1024"},{"name":"Cheese in Ancient Egypt","rarity":"common","id":"cheese-in-ancient-egypt","subtitle":"Lore","details":"Egyptian tomb paintings show cheese being made more than 4,000 years ago, curds strained in reed mats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/History%20of%20Rome%2C%20and%20of%20the%20Roman%20people%2C%20from%20its%20origin%20to%20the%20invasion%20of%20the%20barbarians%20%281883%29%20%2814800175773%29.jpg?width=1024"},{"name":"Cheese in Ancient Rome","rarity":"common","id":"cheese-in-ancient-rome","subtitle":"Lore","details":"Roman writers gave detailed cheese recipes, and soldiers carried hard cheese as marching rations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Romain%20flor%20relief%20of%20timgad.jpg?width=1024"},{"name":"Cheese in the Iliad","rarity":"common","id":"cheese-in-the-iliad","subtitle":"Lore","details":"In the Iliad, a healing drink is mixed with grated goat's cheese, barley and wine for wounded warriors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Illiad%20fragmented%20papyrus.png?width=1024"},{"name":"Cheese It!","rarity":"common","id":"cheese-it","subtitle":"Lore","details":"Nineteenth-century slang for 'stop, run!': 'cheese it' survives in old crime stories, comics and cartoons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nabisco%20brand%20Cheese%20Nips.JPG?width=1024"},{"name":"Cheese Keeper","rarity":"common","id":"cheese-keeper","subtitle":"Serving","details":"A keeper's vented cover and base hold a wedge at serving condition balancing air flow and humidity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Froma%C4%9Doklo%C5%9Do.JPG?width=1024"},{"name":"Cheese Knife","rarity":"common","id":"cheese-knife","subtitle":"Serving","details":"The everyday cheese knife pairs a medium blade with a forked tip for lifting the slice you just cut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Knife%20by%20YAMO.png?width=1024"},{"name":"Cheese Labels","rarity":"common","id":"cheese-labels","subtitle":"Serving","details":"Paper labels and appellation bands on a wheel record its maker, milk and origin before it is ever cut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20150125%20WikiLovesCheese%20Vienna%208889.jpg?width=1024"},{"name":"Cheese Markers","rarity":"common","id":"cheese-markers","subtitle":"Serving","details":"Small flags, picks or chalked labels name each cheese on a crowded board so tasters know what they try.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Route%20marker%2C%20the%20Creamy%20Lancashire%20Cheese%20Trail%20-%20geograph.org.uk%20-%204125255.jpg?width=1024"},{"name":"Cheese Omelette","rarity":"common","id":"cheese-omelette","subtitle":"Dish","details":"Eggs folded around melted cheese so the filling stays soft while the outside sets lightly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20%26%20Mushroom%20Omelette%20-%20The%20Bystander%20Cafe%202023-08-07.jpg?width=1024"},{"name":"Cheese Pasty","rarity":"common","id":"cheese-pasty","subtitle":"Dish","details":"A handheld pastry filled with cheese and onion or potato and baked until the crust crisps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burger%20and%20Cheese%20puffs%20and%20pasties%20at%20Broadstairs%20Kent%20England.jpg?width=1024"},{"name":"Cheese Plate","rarity":"common","id":"cheese-plate","subtitle":"Serving","details":"As a serving, a cheese plate arranges a few contrasting cheeses with fruit, nuts and bread on one plate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tapas%20and%20beer%20at%20restaurant%20Solmu.jpg?width=1024"},{"name":"Cheese Puns","rarity":"common","id":"cheese-puns","subtitle":"Lore","details":"Brie mine, feeling grate, sweet dreams are made of cheese: no food submits to punning more willingly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20with%20coldcut%20plate%20from%20CAPO%20SYP.jpg?width=1024"},{"name":"Cheese Ravioli","rarity":"common","id":"cheese-ravioli","subtitle":"Dish","details":"Italian pasta parcels filled with ricotta and other cheeses and served simply with sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Liat%20Portal%20for%20Foodie%20Disorder%20-%20Four%20cheese%20ravioli%20with%20cream%20sauce.jpg?width=1024"},{"name":"Cheese Shavings","rarity":"common","id":"cheese-shavings","subtitle":"Serving","details":"Thin shavings expose maximum surface area so a hard cheese's aroma blooms the moment they land.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bresaola%20with%20Rocket%20and%20Shavings%20of%20Parmesan.jpg?width=1024"},{"name":"Cheese Slicer","rarity":"common","id":"cheese-slicer","subtitle":"Serving","details":"A board-mounted wire or roller slicer cuts even portions from a block with a single pull of the arm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Several%20cheeses%20with%20a%20slicer%2C%20bread%20and%20milk.JPG?width=1024"},{"name":"Cheese Spreader","rarity":"common","id":"cheese-spreader","subtitle":"Serving","details":"A short blunt blade spreads soft and whipped cheeses onto bread and crackers without tearing them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wooden%20butter%20knife%20isolated%20on%20white%20background.jpg?width=1024"},{"name":"Cheese Stand","rarity":"common","id":"cheese-stand","subtitle":"Serving","details":"A raised stand lifts a wheel or wedge above the board giving it pride of place at a tasting table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20stand%20at%20wine%20fair.jpg?width=1024"},{"name":"Cheese Twists","rarity":"common","id":"cheese-twists","subtitle":"Dish","details":"Strips of puff pastry twisted with grated cheese and baked until crisp and flaky.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheddar%20Cheese%20Twist%20-%20Costa%20Coffee%202025-11-06.jpg?width=1024"},{"name":"Cheese Vat","rarity":"common","id":"cheese-vat","subtitle":"Making","details":"The cheese vat is the wide vessel where milk is warmed, cultured, set, and cut, often with long rakes and wire harps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20130911-OC-RBN-3864%20%289733480935%29.jpg?width=1024"},{"name":"Cheese-Stuffed Peppers","rarity":"common","id":"cheese-stuffed-peppers","subtitle":"Dish","details":"Peppers filled with a cheese mixture and baked until the peppers soften and the top browns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roasted%20bell%20peppers%20stuffed%20with%20spicy%20guacamole%20and%20tunafish%20on%20lettuce%2C%20with%20cheddar%20cheese%2C%20olive%20oil%2C%20and%20black%20pepper%20-%20Massachusetts.jpg?width=1024"},{"name":"Cheesecloth","rarity":"common","id":"cheesecloth","subtitle":"Making","details":"Loosely woven cheesecloth lines moulds and bundles curd, letting whey drain away while holding the fragile solids together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheesecloth%20on%20Sauerkraut%20%285504152472%29.jpg?width=1024"},{"name":"Cheeseheads","rarity":"common","id":"cheeseheads","subtitle":"Lore","details":"Green Bay Packers fans wear foam cheese wedges as hats, turning a teasing nickname into proud Wisconsin regalia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Man%20wearing%20a%20cheese%20hat%20with%20a%20corncob%20pipe.png?width=1024"},{"name":"Cheesy Garlic Bread","rarity":"common","id":"cheesy-garlic-bread","subtitle":"Dish","details":"Bread topped with garlic butter and cheese then baked until the cheese melts and browns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheesy%20Mushrooms%20-%20Toby%20Carvery%202026-10-06.jpg?width=1024"},{"name":"Chipá","rarity":"common","id":"chipa","subtitle":"Dish","details":"Paraguayan cheese breads made with cassava flour and baked into small firm rolls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chipa%20alargada%20tradicional%20-%20Capiov%C3%AD%2C%20Misiones.jpg?width=1024"},{"name":"Coagulation","rarity":"common","id":"coagulation","subtitle":"Making","details":"Coagulation is the moment liquid milk sets into a soft, jelly-like curd that can be cut, drained, and shaped into cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mascarpone%202.jpg?width=1024"},{"name":"Cow's Milk","rarity":"common","id":"cows-milk","subtitle":"Making","details":"Cow's milk is the world's most common cheese milk, prized for its mild flavour, steady supply, and golden, fat-rich curd.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sumerian%20scene%2C%20milking%20cows%20and%20making%20dairy%20products.%20From%20the%20facade%20of%20the%20Temple%20of%20Ninhursag%20at%20Tell%20al-%27Ubaid%2C%20Iraq%2C%202800-2600%20BCE.%20Iraq%20Museum.jpg?width=1024"},{"name":"Curé Nantais","rarity":"common","id":"cure-nantais","subtitle":"Variety","details":"French cow's-milk washed-rind cheese from Brittany, soft and salty with a sea-air tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WikiCheese%20-%20Cur%C3%A9%20nantais%2002.jpg?width=1024"},{"name":"Danbo","rarity":"common","id":"danbo","subtitle":"Variety","details":"Denmark's mild semi-soft staple, a gently tangy everyday cheese sliced for open sandwiches across the country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Danbo%20Cheese.jpg?width=1024"},{"name":"Durrus","rarity":"common","id":"durrus","subtitle":"Variety","details":"Irish washed-rind cow's-milk cheese, semi-soft with an earthy, milky tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ardrahan%20%26%20Durrus%20%2813910989260%29.jpg?width=1024"},{"name":"Enzymes","rarity":"common","id":"enzymes","subtitle":"Making","details":"Enzymes are proteins that drive cheesemaking reactions, from setting milk into curd to slowly building flavour as cheese ages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Separating%20the%20curd%20and%20whey.jpg?width=1024"},{"name":"Esfiha de Queijo","rarity":"common","id":"esfiha-de-queijo","subtitle":"Dish","details":"An open-faced baked dough topped with cheese popular in Brazil with Levantine roots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Esfihas%20sabor%20queijo.%20%2816975013287%29.jpg?width=1024"},{"name":"Fiore Sardo","rarity":"common","id":"fiore-sardo","subtitle":"Variety","details":"Sardinian sheep's-milk cheese, firm and smoky, made by herders in chestnut-leaf moulds and aged for months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fiore%20Sardo%20DOP%20chunk.jpg?width=1024"},{"name":"Formaggio di Fossa","rarity":"common","id":"formaggio-di-fossa","subtitle":"Variety","details":"Italian pit-aged cheese buried in tuff pits for months, emerging firm and pungently aromatic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Formaggio%20di%20fossa.jpg?width=1024"},{"name":"Fresh Curd","rarity":"common","id":"fresh-curd","subtitle":"Making","details":"Fresh curd is cheese before pressing and aging: mild, moist, and squeaky, it can be eaten as-is or become a finished cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fresh%20pressed%20cheese%20in%20vats%2C%20before%20it%20is%20made%20into%20cheese%20curds%2C%20at%20the%20Mountain%20View%20Cheese%20Factory%2C%20Prince%20Edward%20County%2C%20Ontario%20%2826148821788%29.jpg?width=1024"},{"name":"Gaperon","rarity":"common","id":"gaperon","subtitle":"Variety","details":"Auvergne cow's-milk cheese flavoured with garlic and pepper, domed and rustic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wikicheese%20Clermont-Ferrand%20-%20Gaperon%2020220825-02.jpg?width=1024"},{"name":"Goat's Milk","rarity":"common","id":"goats-milk","subtitle":"Making","details":"Goat's milk makes bright white cheese with a tangy bite; its small fat globules give the paste a smooth, close texture.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gorge%20du%20Verdon%20Goat%200254.jpg?width=1024"},{"name":"Grading","rarity":"common","id":"grading","subtitle":"Making","details":"Graders judge aged wheels by look, feel, smell, and a small core sample, checking whether a batch is ready and well made.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Old%20Patea%20Cheese%20Grading%20Store%20-%20panoramio.jpg?width=1024"},{"name":"Graukäse","rarity":"common","id":"graukase","subtitle":"Variety","details":"Tyrolean skim-milk cheese, grey-mould ripened, crumbly and intensely sharp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tyrolean%20grey%20cheese%20Loaf%20Cut.jpg?width=1024"},{"name":"Great British Cheese Festival","rarity":"common","id":"great-british-cheese-festival","subtitle":"Lore","details":"This travelling festival pairs hundreds of cheeses with masterclasses, markets and a lot of confident tasting notes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20stall%2C%20Borough%20Market%2C%20Southwark%20-%20geograph.org.uk%20-%205163719.jpg?width=1024"},{"name":"Grilled Halloumi","rarity":"common","id":"grilled-halloumi","subtitle":"Dish","details":"Slices of Cypriot halloumi grilled until marked and golden while holding their shape firmly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grilled%20halloumi%2C%20%CE%A0%CE%BB%CE%AC%CE%BA%CE%B1%2C%2031st%20Ave.jpg?width=1024"},{"name":"Gubbeen","rarity":"common","id":"gubbeen","subtitle":"Variety","details":"Irish surface-ripened cow's-milk cheese, semi-soft and mushroomy under a pink-brown rind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%2061%20bg%20080106.jpg?width=1024"},{"name":"Hand Grater","rarity":"common","id":"hand-grater","subtitle":"Serving","details":"A flat or curved hand grater gives quick controlled shreds from a wedge held directly over the food.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grater%20%28scraper%29%20Punta%20Corda%2C%20Toledo%20District%20%28later%2020th%20c.%29%20-%20MIM%20PHX.jpg?width=1024"},{"name":"Handkäse","rarity":"common","id":"handkase","subtitle":"Variety","details":"German sour-milk cheese from Hesse, translucent and tangy, served 'with music' — onion and vinegar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Junger%20Handk%C3%A4se%2003%20WikiCheese%20Lokal%20K.jpg?width=1024"},{"name":"Harzer","rarity":"common","id":"harzer","subtitle":"Variety","details":"German sour-milk cheese, low in fat, firm and pungent, often seasoned with caraway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Harzer%20K%C3%A4se%2013%20WikiCheese%20Lokal%20K.jpg?width=1024"},{"name":"Humboldt Fog","rarity":"common","id":"humboldt-fog","subtitle":"Variety","details":"Californian goat cheese with a line of ash through its centre, bright and lemony as it ripens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%2030%20bg%20051906.jpg?width=1024"},{"name":"Imeruli Khachapuri","rarity":"common","id":"imeruli-khachapuri","subtitle":"Dish","details":"A round Georgian cheese-filled bread with the cheese sealed inside rather than on top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Georgian%20Khachapuri%20cheese%20bread.jpg?width=1024"},{"name":"International Cheese Awards","rarity":"common","id":"international-cheese-awards","subtitle":"Lore","details":"Held in Cheshire since 1897, these awards draw thousands of entries to one of the world's biggest cheese shows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2015-01-25%20Jersey%20Blue%20-%20St%C3%A4dtch%C3%A4si%20Lichtensteig%20-%20der%20Schweizer%20-%20hu%20-%208003.jpg?width=1024"},{"name":"Jameed","rarity":"common","id":"jameed","subtitle":"Variety","details":"Jordanian dried fermented yogurt cheese, rock-hard balls rehydrated for mansaf sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jameed.JPG?width=1024"},{"name":"Kalari","rarity":"common","id":"kalari","subtitle":"Variety","details":"Jammu cheese from cow or buffalo milk, dense and stretchy when fried, sold as flat discs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Famous%20Kalaadi%20of%20Ramnagar.jpg?width=1024"},{"name":"Kaspressknödel","rarity":"common","id":"kaspressknodel","subtitle":"Dish","details":"Austrian flattened cheese dumplings that are pan-fried and served in broth or with salad.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kaspresskn%C3%B6del%20mit%20Salat.jpg?width=1024"},{"name":"Kesong Puti","rarity":"common","id":"kesong-puti","subtitle":"Variety","details":"Philippine fresh white cheese from carabao or cow milk, soft, salty and eaten with bread.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kesong%20puti.jpg?width=1024"},{"name":"Kopanisti","rarity":"common","id":"kopanisti","subtitle":"Variety","details":"Greek Aegean cheese beaten until soft, peppery and sharply pungent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%CE%9A%CE%BF%CF%80%CE%B1%CE%BD%CE%B9%CF%83%CF%84%CE%AE%202844.jpg?width=1024"},{"name":"Lactic Acid","rarity":"common","id":"lactic-acid","subtitle":"Making","details":"As starter bacteria ferment lactose, the lactic acid they produce lowers the milk's pH and helps it turn from liquid to curd.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D8%A7%D9%84%D9%84%D8%A8%D9%86%20%D8%A7%D9%84%D8%AD%D8%A7%D9%85%D8%B6%28%D8%A7%D9%84%D8%B1%D9%88%D8%A8%29.jpg?width=1024"},{"name":"Leaf-Wrapped Wheel","rarity":"common","id":"leaf-wrapped-wheel","subtitle":"Serving","details":"Fig, chestnut or vine leaves wrapped around a small cheese protect it and perfume the paste as it ripens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banon1.jpg?width=1024"},{"name":"Lighvan","rarity":"common","id":"lighvan","subtitle":"Variety","details":"Iranian brined sheep's-milk cheese from East Azerbaijan, crumbly with holes and a salty tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lighvan%20cheese%201.jpg?width=1024"},{"name":"Maytag Blue","rarity":"common","id":"maytag-blue","subtitle":"Variety","details":"American cow's-milk blue from Iowa, cave-aged, dense and sharply tangy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MaytagBlueCheesePackageAndRamekin.jpg?width=1024"},{"name":"Medieval Monastery Cheese","rarity":"common","id":"medieval-monastery-cheese","subtitle":"Lore","details":"Monasteries kept careful dairy herds and recipes, preserving cheesemaking knowledge through the Middle Ages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abtei%20Bellelay%20stitch%2001.jpg?width=1024"},{"name":"Melanzane alla Parmigiana","rarity":"common","id":"melanzane-alla-parmigiana","subtitle":"Dish","details":"Italian layers of aubergine with tomato and Parmesan and mozzarella baked until golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melanzane%20alla%20Parmigiana.jpg?width=1024"},{"name":"Metsovone","rarity":"common","id":"metsovone","subtitle":"Variety","details":"Greek smoked cow's-milk cheese from Metsovo, cylindrical and firm with a woody aroma.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%CE%9C%CE%B5%CF%84%CF%83%CE%BF%CE%B2%CF%8C%CE%BD%CE%B5%206304.jpg?width=1024"},{"name":"Minas Cheese","rarity":"common","id":"minas-cheese","subtitle":"Variety","details":"Brazilian fresh cow's-milk cheese, soft, white and mild, a breakfast staple in Minas Gerais.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queijos%20de%20Curitiba%20-%20Rodrigo%20Ghedin.jpg?width=1024"},{"name":"Mozzarella in Carrozza","rarity":"common","id":"mozzarella-in-carrozza","subtitle":"Dish","details":"An Italian fried mozzarella sandwich coated in crumbs and cooked until crisp outside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mozzarella%20in%20Carrozza%20-%20Tavola%20Di%20Famiglia%202026-02-27.jpg?width=1024"},{"name":"Murazzano","rarity":"common","id":"murazzano","subtitle":"Variety","details":"Piedmont sheep's-milk Robiola-style cheese, soft, white and gently sweet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Murazzano%20DOP%20%28formaggio%29.jpg?width=1024"},{"name":"Murol","rarity":"common","id":"murol","subtitle":"Variety","details":"French cow's-milk cheese with a hole in the middle, mild and supple under an orange rind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Murol%20%28cheese%29%201.jpg?width=1024"},{"name":"Mysost","rarity":"common","id":"mysost","subtitle":"Variety","details":"Norwegian whey cheese, lighter and milder than Brunost, sweet and caramel-toned.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brunost.jpg?width=1024"},{"name":"Myzithra","rarity":"common","id":"myzithra","subtitle":"Variety","details":"Greek whey cheese eaten fresh and soft, or salted and aged rock-hard for grating over pasta and pies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mizithra.jpg?width=1024"},{"name":"Nagelkaas","rarity":"common","id":"nagelkaas","subtitle":"Variety","details":"Dutch clove cheese from Friesland, studded with cloves and cumin, firm and spicy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belegen%20nagelkaas%20en%20belegen%20boerenkaas.jpg?width=1024"},{"name":"Nisa","rarity":"common","id":"nisa","subtitle":"Variety","details":"Portuguese sheep's-milk cheese, semi-hard and cylindrical with a tangy, salty bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queijo%20de%20nisa.jpg?width=1024"},{"name":"Nökkelost","rarity":"common","id":"nokkelost","subtitle":"Variety","details":"Norwegian cow's-milk cheese spiced with cumin and cloves, semi-firm and aromatic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leidse%20kaas.JPG?width=1024"},{"name":"Old Amsterdam","rarity":"common","id":"old-amsterdam","subtitle":"Variety","details":"Dutch aged Gouda-style cheese with a firm, crystalline bite and deep caramel flavour, stacked in rounds in Amsterdam shops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Whole%20rounds%20of%20Old%20Amsterdam.jpg?width=1024"},{"name":"Pico","rarity":"common","id":"pico","subtitle":"Variety","details":"Portuguese cow's-milk cheese from the Azores island of Pico, soft and salty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Pico%20by%20Germain.jpg?width=1024"},{"name":"Picodon","rarity":"common","id":"picodon","subtitle":"Variety","details":"Rhône-Alpes goat cheese, small and firm, sweet when young and piquant when aged.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wikicheese%20-%20Picodon%20-%2020150417%20-%20003.jpg?width=1024"},{"name":"Pierogi Ruskie","rarity":"common","id":"pierogi-ruskie","subtitle":"Dish","details":"Polish dumplings filled with potato and curd cheese and often topped with fried onions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Food%20in%20Lichen%20Stary%20%28pierogi%20ruskie%2C%20dumplings%29.jpg?width=1024"},{"name":"Pélardon","rarity":"common","id":"pelardon","subtitle":"Variety","details":"Languedoc goat cheese, small discs with a wrinkled rind and clean, tangy paste.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/P%C3%A9lardon%2005.jpg?width=1024"},{"name":"Quark","rarity":"common","id":"quark","subtitle":"Variety","details":"German fresh cow's-milk cheese, smooth and tangy, spoonable like a thick yogurt-cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skimmed%20milk%20quark%20on%20spoon.jpg?width=1024"},{"name":"Queijo Coalho","rarity":"common","id":"queijo-coalho","subtitle":"Variety","details":"Brazilian firm cow's-milk cheese on skewers, made to grill without melting away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coalho%20cheese.jpg?width=1024"},{"name":"Queso de Ulloa","rarity":"common","id":"queso-de-ulloa","subtitle":"Variety","details":"Galician cow's-milk cheese, soft and creamy with a clean, buttery taste.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mallorca-K%C3%A4se-1.JPG?width=1024"},{"name":"Queso Fundido","rarity":"common","id":"queso-fundido","subtitle":"Dish","details":"A Mexican dish of cheese melted in a hot dish and eaten by spooning it into warm tortillas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queso%20Flameado%20de%20Oaxaca.jpg?width=1024"},{"name":"Rigotte de Condrieu","rarity":"common","id":"rigotte-de-condrieu","subtitle":"Variety","details":"Small Rhône goat cheese, firm when aged and soft when young, gently goaty and nutty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rigottes%20de%20Condrieu.JPG?width=1024"},{"name":"Rind","rarity":"common","id":"rind","subtitle":"Making","details":"A rind forms on a cheese's surface as it dries and ages; some rinds are eaten, others are scrubbed, washed, or cut away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20130919-RD-RBN-4306%20%2813062786834%29.jpg?width=1024"},{"name":"Rocamadour","rarity":"common","id":"rocamadour","subtitle":"Variety","details":"Tiny Lot goat cheese, creamy under a wrinkled skin, eaten fresh or warm on toast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rocamadour%20AOC.jpg?width=1024"},{"name":"Rotary Grater","rarity":"common","id":"rotary-grater","subtitle":"Serving","details":"A hand crank presses cheese against a rotating drum producing a steady shower of fine gratings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/74679000%20RotaryGrater%20LifestyleSalad6.5x6.2.jpg?width=1024"},{"name":"Rygeost","rarity":"common","id":"rygeost","subtitle":"Variety","details":"Danish smoked fresh cheese, soft and tangy, traditionally smoked over nettles and straw.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rygeost%20%286089231222%29.jpg?width=1024"},{"name":"Saint-Félicien","rarity":"common","id":"saint-felicien","subtitle":"Variety","details":"French cow's-milk cheese, soft and creamy with a bloomy rind and rich lactic tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saint-F%C3%A9licien%2002.jpg?width=1024"},{"name":"Saint-Marcellin","rarity":"common","id":"saint-marcellin","subtitle":"Variety","details":"French cow's-milk disc, soft and runny when ripe, sold in small ceramic pots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wikicheese%20-%20Saint-marcellin%20-%2020150417%20-%20010.jpg?width=1024"},{"name":"San Simón da Costa","rarity":"common","id":"san-simon-da-costa","subtitle":"Variety","details":"Galician cow's-milk cheese smoked over birch, teardrop-shaped with a golden rind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/San%20Simon%20Da%20Costa%20cheese.JPG?width=1024"},{"name":"Sardo Argentino","rarity":"common","id":"sardo-argentino","subtitle":"Variety","details":"Argentinian hard grating cheese in the Sardinian tradition, salty and firm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sardo.jpg?width=1024"},{"name":"Sheep's Milk","rarity":"common","id":"sheeps-milk","subtitle":"Making","details":"Sheep's milk is richer than cow's milk, with more fat and protein, so a small amount of milk yields a lot of cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sheep%20milking%20at%20Great%20Bircham%20Windmill.jpg?width=1024"},{"name":"Squacquerone","rarity":"common","id":"squacquerone","subtitle":"Variety","details":"Romagna cow's-milk cheese, very soft and spreadable, milky and lightly tangy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Squacquerone%20Romagnolo%201.jpg?width=1024"},{"name":"Stinking Bishop","rarity":"common","id":"stinking-bishop","subtitle":"Variety","details":"English washed-rind cow's-milk cheese, famously pungent yet soft and creamy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stinking%20Bishop%20cheese.jpg?width=1024"},{"name":"The Cheese Emoji","rarity":"common","id":"the-cheese-emoji","subtitle":"Lore","details":"The cheese wedge emoji, a holey orange-yellow triangle, joined the standard emoji set in 2015.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Twemoji12%201f9c0.svg?width=1024"},{"name":"The Cheese Touch","rarity":"common","id":"the-cheese-touch","subtitle":"Lore","details":"No one dares touch the mouldy slice on the school court in Diary of a Wimpy Kid: the Cheese Touch spreads by contact.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schoolyard%20Henry-Benrath-Schule%20Friedberg%202021-04-02%2008.jpg?width=1024"},{"name":"The Cheese Wedge","rarity":"common","id":"the-cheese-wedge","subtitle":"Serving","details":"The classic wedge is cut radially from a wheel, carrying a point at the centre and a band of rind at the back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wedge%20of%20Cheese%20sculpted%20in%20concrete%20-%20geograph.org.uk%20-%201555528.jpg?width=1024"},{"name":"The First Cheese Factory","rarity":"common","id":"the-first-cheese-factory","subtitle":"Lore","details":"One of the first cheese factories opened in Switzerland in 1815; the first in the US followed in New York in 1851.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ngaere%20Dairy%20Factory.jpg?width=1024"},{"name":"The Half Wheel","rarity":"common","id":"the-half-wheel","subtitle":"Serving","details":"Cutting a wheel in half exposes the full paste at once, the moment a cheesemonger checks ripeness and aroma.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Half%20wheel%20parmesan%20cheese.jpg?width=1024"},{"name":"The Mini Wheel","rarity":"common","id":"the-mini-wheel","subtitle":"Serving","details":"Small whole wheels ripen faster than large ones and are sized to be sold, gifted and finished whole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20Detail%20inside%20a%20Hobbit%20Hole%2C%20Hobbiton%20Movie%20Set%2C%20Matamata%2C%20New%20Zealand%202016%20%2850797307106%29.jpg?width=1024"},{"name":"The Rind","rarity":"common","id":"the-rind","subtitle":"Serving","details":"The rind is a cheese's skin and story: it shields the paste, hosts ripening microbes and is often edible.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20rind%20microbial%20community.png?width=1024"},{"name":"Wartime Government Cheddar","rarity":"common","id":"wartime-government-cheddar","subtitle":"Lore","details":"During wartime rationing, Britain funnelled milk into one plain 'Government Cheddar', and farmhouse cheeses nearly vanished.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Government%20cheese.jpg?width=1024"},{"name":"Weisslacker","rarity":"common","id":"weisslacker","subtitle":"Variety","details":"German cow's-milk cheese cured in brine, sharp and salty; nicknamed beer cheese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beer%20cheese%20soup%20with%20pretzels.jpg?width=1024"},{"name":"Yarg","rarity":"common","id":"yarg","subtitle":"Variety","details":"Cornish cow's-milk cheese wrapped in nettle leaves, crumbly and lemony in the centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wild%20Garlic%20Yarg.jpg?width=1024"},{"name":"Évora","rarity":"common","id":"evora","subtitle":"Variety","details":"Alentejo sheep's-milk cheese, thistle-set and intensely flavoured, made small and sharp around the city of Évora.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queijo%20de%20%C3%89vora%20-%202.JPG?width=1024"}]});
